/* Палитры LIGHT_COLORS / DARK_COLORS, COLORS, pageBackground и PAGE_BG_SIZE — в src/ui/theme.js */

function toneForValue(v) {
  if (v >= 70) return COLORS.sage;
  if (v >= 40) return COLORS.yellow;
  if (v > 0) return COLORS.rust;
  return COLORS.line;
}

function lessonFillStyle(pct) {
  if (!pct || pct <= 0) {
    return { background: COLORS.surface, border: `1px solid ${COLORS.line}` };
  }
  const color = toneForValue(pct);
  return {
    background: `linear-gradient(to right, ${color}2E ${pct}%, ${COLORS.surface} ${pct}%)`,
    border: `1px solid ${color}77`,
  };
}

/* ===== ТАЙМЕР СЕССИИ — вынесен в src/ui/SessionTimer.jsx (вместе с dayKeyUTC5) ===== */

/* Навигация из двух групп: слева служебное меню, справа учебные модули. */
function TabsBar({ menu, modules, active, onPick }) {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const drawerRef = React.useRef(null);

  useEffect(() => {
    if (!drawerOpen) return;
    const onDocClick = (e) => { if (drawerRef.current && !drawerRef.current.contains(e.target)) setDrawerOpen(false); };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [drawerOpen]);

  const btn = (key, label, Icon, isActive, onClick) => (
    <button key={key} onClick={onClick || (() => onPick(key))}
      className="flex items-center gap-1.5 px-3.5 py-2 rounded-full text-sm font-medium transition whitespace-nowrap"
      style={{ background: isActive ? COLORS.onyx : "transparent",
               color: isActive ? COLORS.onyxText : COLORS.inkSoft,
               border: `1px solid ${isActive ? COLORS.onyx : COLORS.line}` }}>
      <Icon size={15} /> {label}
    </button>
  );

  const menuActive = menu.some(([k]) => k === active);

  return (
    <nav className="flex items-center gap-3 mt-6 flex-wrap relative">
      <div className="relative" ref={drawerRef}>
        <button onClick={() => setDrawerOpen((v) => !v)}
          className="flex items-center gap-1.5 px-3.5 py-2 rounded-full text-sm font-medium transition"
          style={{ background: menuActive ? COLORS.onyx : COLORS.paperDeep,
                   color: menuActive ? COLORS.onyxText : COLORS.inkSoft,
                   border: `1px solid ${menuActive ? COLORS.onyx : COLORS.line}` }}>
          <MoreHorizontal size={15} />
          {menuActive ? menu.find(([k]) => k === active)[1] : "Ещё"}
          <ChevronDown size={13} style={{ transform: drawerOpen ? "rotate(180deg)" : "none", transition: "transform .15s ease" }} />
        </button>
        {drawerOpen && (
          <div className="absolute left-0 top-full mt-1.5 p-1.5 z-30 flex flex-col gap-0.5 ms-rise"
            style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, borderRadius: 20, boxShadow: "0 8px 24px rgba(0,0,0,0.12)", minWidth: 160 }}>
            {menu.map(([k, l, I]) => btn(k, l, I, active === k, () => { onPick(k); setDrawerOpen(false); }))}
          </div>
        )}
      </div>
      <span style={{ width: 1, height: 22, background: COLORS.line, flexShrink: 0 }} />
      <div className="flex gap-1.5 flex-wrap">
        {modules.map(([k, l, I]) => btn(k, l, I, active === k))}
      </div>
    </nav>
  );
}

