function Pill({ children, tone = "blue" }) {
  const map = {
    blue: { bg: COLORS.blueSoft, fg: COLORS.blue },
    amber: { bg: COLORS.amberSoft, fg: COLORS.amber },
    sage: { bg: COLORS.sageSoft, fg: COLORS.sage },
    teal: { bg: COLORS.tealSoft, fg: COLORS.teal },
    rust: { bg: COLORS.rustSoft, fg: COLORS.rust },
  };
  const c = map[tone] || map.blue;
  return (
    <span
      className="text-xs font-medium px-2 py-0.5 rounded-full inline-block"
      style={{ background: c.bg, color: c.fg, fontFamily: "'IBM Plex Mono', monospace" }}
    >
      {children}
    </span>
  );
}

function ForgettingCurve({ points }) {
  const W = 640;
  const H = 220;
  const padL = 40;
  const padB = 30;
  const plotW = W - padL - 20;
  const plotH = H - padB - 20;
  const curveY = (x) => Math.exp(-2.1 * x);
  const pathPts = [];
  for (let i = 0; i <= 60; i++) {
    const x = i / 60;
    const y = curveY(x);
    pathPts.push(`${padL + x * plotW},${20 + (1 - y) * plotH}`);
  }
  const pathD = "M " + pathPts.join(" L ");

  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-auto" role="img" aria-label="Кривая забывания с положением карточек">
      {[0, 0.25, 0.5, 0.75, 1].map((f, i) => (
        <line key={i} x1={padL} x2={W - 20} y1={20 + f * plotH} y2={20 + f * plotH} stroke={COLORS.line} strokeWidth="1" strokeDasharray="2,4" />
      ))}
      <line x1={padL} x2={padL} y1={20} y2={H - padB} stroke={COLORS.ink} strokeWidth="1.5" />
      <line x1={padL} x2={W - 20} y1={H - padB} y2={H - padB} stroke={COLORS.ink} strokeWidth="1.5" />
      <text x={padL} y={14} fontSize="11" fill={COLORS.inkSoft} fontFamily="IBM Plex Mono, monospace">память, %</text>
      <text x={W - 90} y={H - 10} fontSize="11" fill={COLORS.inkSoft} fontFamily="IBM Plex Mono, monospace">время с повторения</text>
      <path d={pathD} fill="none" stroke={COLORS.blue} strokeWidth="2.5" />
      {points.map((p, i) => {
        const x = Math.min(p.progress, 1.28);
        const y = curveY(Math.min(x, 1));
        const cx = padL + Math.min(x, 1) * plotW;
        const cy = 20 + (1 - y) * plotH;
        const fill = p.mastered ? COLORS.sage : x >= 0.98 ? COLORS.rust : COLORS.amber;
        return <circle key={i} cx={cx} cy={cy} r="5" fill={fill} stroke={COLORS.paper} strokeWidth="1.5" />;
      })}
    </svg>
  );
}

