/* Мини-тест внутри урока: вопрос, варианты, мгновенная проверка с разбором. */

/* Словарная карточка: определение, термин с аббревиатурой и пояснение мелким шрифтом. */
function TGloss({ title, note, items }) {
  const [hide, setHide] = useState(false);
  const [order, setOrder] = useState(null);
  const [shown, setShown] = useState({});
  const rows = order ? order.map((i) => items[i]) : items;
  const keyOf = (it) => it.term;

  const reshuffle = () => {
    const idx = items.map((_, i) => i);
    for (let i = idx.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [idx[i], idx[j]] = [idx[j], idx[i]];
    }
    setOrder(idx); setShown({});
  };

  return (
    <div className="my-4 rounded-xl overflow-hidden" style={{ border: `1px solid ${COLORS.line}` }}>
      {title && (
        <div className="px-4 py-2 text-xs font-semibold uppercase tracking-wide"
          style={{ background: COLORS.sageSoft, color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>{title}</div>
      )}
      <div className="px-3 py-2 flex items-center gap-2 flex-wrap"
        style={{ background: COLORS.paperDeep, borderBottom: `1px solid ${COLORS.line}` }}>
        <button onClick={() => { setHide(!hide); setShown({}); }}
          className="px-3 py-1 rounded-full text-xs font-semibold"
          style={{ background: hide ? COLORS.sage : COLORS.surfaceSolid, color: hide ? "#FFFFFF" : COLORS.inkSoft,
                   border: `1px solid ${hide ? COLORS.sage : COLORS.line}` }}>
          {hide ? "Самопроверка включена" : "Самопроверка"}
        </button>
        <button onClick={reshuffle} className="px-3 py-1 rounded-full text-xs font-semibold"
          style={{ background: COLORS.surfaceSolid, color: COLORS.inkSoft, border: `1px solid ${COLORS.line}` }}>
          Перемешать
        </button>
        {hide && <span className="text-xs" style={{ color: COLORS.inkSoft }}>нажмите на скрытую ячейку, чтобы проверить себя</span>}
      </div>
      {note && (
        <p className="px-3 py-2 text-xs leading-relaxed"
          style={{ color: COLORS.inkSoft, background: COLORS.surface, borderBottom: `1px solid ${COLORS.line}` }}>{note}</p>
      )}
      <div style={{ overflowX: "auto" }}>
        <table className="w-full" style={{ borderCollapse: "collapse", minWidth: "420px" }}>
          <thead>
            <tr>
              <th className="text-left px-3 py-2 text-xs font-semibold"
                style={{ width: "34%", background: COLORS.sageSoft, color: COLORS.sage, borderBottom: `1px solid ${COLORS.line}` }}>Термин</th>
              <th className="text-left px-3 py-2 text-xs font-semibold"
                style={{ background: COLORS.surface, color: COLORS.inkSoft, borderBottom: `1px solid ${COLORS.line}` }}>Определение и пояснение</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((it, i) => {
              const open = shown[keyOf(it)];
              const masked = hide && !open;
              const bg = i % 2 ? COLORS.surface : COLORS.surfaceSolid;
              return (
                <tr key={keyOf(it)}>
                  <td className="px-3 py-2.5 text-sm align-top"
                    onClick={() => masked && setShown((p) => ({ ...p, [keyOf(it)]: true }))}
                    style={{ background: bg, cursor: masked ? "pointer" : "default",
                             borderLeft: `2px solid ${COLORS.sage}59`,
                             borderBottom: i < rows.length - 1 ? `1px solid ${COLORS.line}` : "none" }}>
                    <div style={{ filter: masked ? "blur(5px)" : "none", userSelect: masked ? "none" : "auto", transition: "filter .15s" }}>
                      <span className="font-semibold" style={{ color: COLORS.ink }}>{it.term}</span>
                      {it.abbr && (
                        <span className="ml-1.5 text-xs px-1.5 py-0.5 rounded inline-block"
                          style={{ background: COLORS.sageSoft, color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>{it.abbr}</span>
                      )}
                    </div>
                    {it.neu && !masked && (
                      <span className="mt-1 text-xs px-1.5 py-0.5 rounded inline-block"
                        style={{ background: COLORS.amberSoft, color: COLORS.amber }}>новое</span>
                    )}
                  </td>
                  <td className="px-3 py-2.5 text-sm align-top"
                    style={{ color: COLORS.inkSoft, background: bg,
                             borderLeft: `1px solid ${COLORS.line}`,
                             borderBottom: i < rows.length - 1 ? `1px solid ${COLORS.line}` : "none" }}>
                    <p className="leading-snug">{it.def}</p>
                    {it.hint && <p className="mt-1 leading-snug" style={{ fontSize: "11px", opacity: 0.75 }}>{it.hint}</p>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}


/* Мини-тест внутри урока: вопрос, варианты, мгновенная проверка с разбором. */
function Q1Quiz({ title = "Мини-тест по уроку", items }) {
  const [picked, setPicked] = useState({});
  const answered = Object.keys(picked).length;
  const right = items.filter((it, i) => picked[i] === it.a).length;
  return (
    <div className="my-5 rounded-xl p-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.sage}55` }}>
      <div className="flex items-center justify-between mb-3">
        <p className="text-xs font-semibold uppercase tracking-wide" style={{ color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>{title}</p>
        <span className="text-xs" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{right} / {items.length}</span>
      </div>
      <div className="space-y-3">
        {items.map((it, i) => {
          const sel = picked[i];
          return (
            <div key={i} className="rounded-lg p-3" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
              <p className="text-sm mb-2" style={{ color: COLORS.ink }}>{i + 1}. {it.q}</p>
              <div className="space-y-1">
                {it.opts.map((o, oi) => {
                  const on = sel === oi;
                  const showRight = sel !== undefined && oi === it.a;
                  const showWrong = on && sel !== it.a;
                  return (
                    <button key={oi} disabled={sel !== undefined} onClick={() => setPicked((pr) => ({ ...pr, [i]: oi }))}
                      className="w-full text-left px-3 py-1.5 rounded text-sm"
                      style={{ background: showRight ? COLORS.sageSoft : showWrong ? COLORS.rustSoft : COLORS.paperDeep,
                               border: `1px solid ${showRight ? COLORS.sage : showWrong ? COLORS.rust : COLORS.line}`, color: COLORS.ink }}>
                      {o}
                    </button>
                  );
                })}
              </div>
              {sel !== undefined && <p className="text-xs mt-2 leading-relaxed" style={{ color: COLORS.inkSoft }}>{it.why}</p>}
            </div>
          );
        })}
      </div>
      {answered === items.length && (
        <button onClick={() => setPicked({})} className="mt-3 px-4 py-1.5 rounded-full text-xs font-semibold" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
          Пройти заново
        </button>
      )}
    </div>
  );
}

