const Q1_THEME_LABELS = { micro: "Микроэкономика", macro: "Макроэкономика", fin: "Финансы", world: "Мировая экономика" };

/* Похожесть определений: чем больше общих значимых слов, тем более коварен дистрактор. */
function q1Similar(a, b) {
  const w = (x) => new Set(String(x).toLowerCase().split(/[^а-яa-z]+/).filter((v) => v.length > 4));
  const A = w(a), B = w(b);
  let c = 0;
  A.forEach((v) => { if (B.has(v)) c++; });
  return c;
}


/* ---- История попыток 1 тура: хранится через window.storage, как и остальной прогресс ---- */
const Q1_HIST_KEY = "q1-history";

async function q1LoadHistory() {
  try {
    const r = await window.storage.get(Q1_HIST_KEY);
    if (!r) return [];
    const v = typeof r === "string" ? r : r.value;
    const parsed = JSON.parse(v);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) { return []; }
}

async function q1SaveAttempt(rec) {
  try {
    const prev = await q1LoadHistory();
    const next = [{ ...rec, ts: Date.now() }, ...prev].slice(0, 60);
    await window.storage.set(Q1_HIST_KEY, JSON.stringify(next));
    return next;
  } catch (e) { return null; }
}

function q1FmtDate(ts) {
  try {
    const d = new Date(ts);
    return `${String(d.getDate()).padStart(2, "0")}.${String(d.getMonth() + 1).padStart(2, "0")} ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
  } catch (e) { return ""; }
}

function Q1Progress() {
  const [hist, setHist] = useState(null);
  useEffect(() => { q1LoadHistory().then(setHist); }, []);

  if (hist === null) return <p className="text-sm" style={{ color: COLORS.inkSoft }}>Загружаю историю…</p>;
  if (!hist.length) {
    return (
      <div className="rounded-2xl p-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}` }}>
        <p className="text-sm" style={{ color: COLORS.inkSoft }}>
          Попыток пока нет. Пройдите пробный вариант или соберите тест в конструкторе —
          результаты начнут накапливаться здесь, и станет видно, какие темы проседают.
        </p>
      </div>
    );
  }

  const byTheme = {};
  hist.forEach((h) => {
    if (!h.themes) return;
    Object.keys(h.themes).forEach((k) => {
      if (!byTheme[k]) byTheme[k] = { right: 0, total: 0 };
      byTheme[k].right += h.themes[k].right;
      byTheme[k].total += h.themes[k].total;
    });
  });
  const themeRows = Object.keys(byTheme)
    .map((k) => ({ k, pct: byTheme[k].total ? Math.round((byTheme[k].right / byTheme[k].total) * 100) : 0, ...byTheme[k] }))
    .sort((a, b) => a.pct - b.pct);
  const weakest = themeRows.filter((r) => r.total >= 5 && r.pct < 70);

  const exams = hist.filter((h) => h.kind === "exam");
  const best = exams.length ? Math.max(...exams.map((e) => e.score)) : null;

  return (
    <div>
      <div className="grid grid-cols-2 gap-2 mb-4">
        <div className="rounded-2xl p-3" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
          <p className="text-xs" style={{ color: COLORS.inkSoft }}>Всего попыток</p>
          <p className="text-xl font-bold" style={{ color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }}>{hist.length}</p>
        </div>
        <div className="rounded-2xl p-3" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
          <p className="text-xs" style={{ color: COLORS.inkSoft }}>Лучший балл варианта</p>
          <p className="text-xl font-bold" style={{ color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }}>{best === null ? "—" : best}</p>
        </div>
      </div>

      {themeRows.length > 0 && (
        <div className="mb-4">
          <p className="text-xs font-semibold uppercase tracking-wide mb-2" style={{ color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>Темы по точности</p>
          <div className="space-y-2">
            {themeRows.map((r) => (
              <div key={r.k} className="rounded-xl p-3" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
                <div className="flex items-center justify-between mb-1">
                  <span className="text-sm" style={{ color: COLORS.ink }}>{Q1_THEME_LABELS[r.k] || r.k}</span>
                  <span className="text-xs" style={{ color: r.pct < 70 ? COLORS.rust : COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>
                    {r.pct}% · {r.right}/{r.total}
                  </span>
                </div>
                <div className="h-1.5 rounded-full overflow-hidden" style={{ background: COLORS.paperDeep }}>
                  <div style={{ width: `${r.pct}%`, height: "100%", background: r.pct < 70 ? COLORS.rust : COLORS.sage }} />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {weakest.length > 0 && (
        <TKey>
          Проседают: {weakest.map((r) => Q1_THEME_LABELS[r.k] || r.k).join(", ")}. Соберите в
          конструкторе тест из 20 заданий только по этим темам — это примерно десять минут.
        </TKey>
      )}

      <p className="text-xs font-semibold uppercase tracking-wide mb-2 mt-4" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>Последние попытки</p>
      <div className="space-y-1.5">
        {hist.slice(0, 12).map((h, i) => (
          <div key={i} className="flex items-center justify-between rounded-xl px-3 py-2"
            style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
            <div>
              <p className="text-sm" style={{ color: COLORS.ink }}>{h.label}</p>
              <p className="text-xs" style={{ color: COLORS.inkSoft }}>{q1FmtDate(h.ts)}</p>
            </div>
            <span className="text-sm font-semibold" style={{ color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }}>
              {h.kind === "exam" ? `${h.score} / ${h.max}` : `${h.score} / ${h.max}`}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

function Q1TermDrill() {
  const [themes, setThemes] = useState(["micro", "macro", "fin", "world"]);
  const [count, setCount] = useState(20);
  const [dir, setDir] = useState("mix");
  const [hard, setHard] = useState(true);
  const [qs, setQs] = useState(null);
  const [idx, setIdx] = useState(0);
  const [ans, setAns] = useState({});
  const [left, setLeft] = useState(0);
  const [over, setOver] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    if (!qs || over) return;
    if (left <= 0) { setOver(true); return; }
    const id = setTimeout(() => setLeft((v) => v - 1), 1000);
    return () => clearTimeout(id);
  }, [qs, left, over]);

  const pool = Q1_TERM_BANK.filter((x) => themes.includes(x.th));

  const build = () => {
    const hardPool = hard ? shuffleArray(Q1_HARD.filter((h) => themes.includes(h.th))) : [];
    const hardTake = hard ? Math.min(hardPool.length, Math.round(count * 0.4)) : 0;
    const hardQs = hardPool.slice(0, hardTake).map((h, i) => {
      const opts = shuffleArray(h.opts.map((o, oi) => ({ o, oi })));
      return {
        it: { t: h.q, d: h.q, h: h.why, th: h.th },
        asTerm: true,
        hard: true,
        prompt: h.q,
        opts: opts.map((x) => x.o),
        a: opts.findIndex((x) => x.oi === h.a),
      };
    });
    const src = shuffleArray(pool).slice(0, Math.max(0, Math.min(count, pool.length) - hardTake));
    const made = src.map((it, i) => {
      const sameTheme = Q1_TERM_BANK.filter((x) => x.th === it.th && x.t !== it.t);
      const ranked = sameTheme
        .map((x) => ({ x, sc: q1Similar(x.d, it.d) + Math.random() }))
        .sort((a, b) => b.sc - a.sc)
        .slice(0, 8)
        .map((o) => o.x);
      const wrong = shuffleArray(ranked).slice(0, 3);
      const asTerm = dir === "term" ? true : dir === "def" ? false : i % 2 === 0;
      const opts = shuffleArray([it, ...wrong]);
      return {
        it,
        asTerm,
        prompt: asTerm ? it.d : it.t,
        opts: opts.map((o) => (asTerm ? o.t : o.d)),
        a: opts.findIndex((o) => o.t === it.t),
      };
    });
    const all = shuffleArray([...made, ...hardQs]);
    setQs(all); setIdx(0); setAns({}); setOver(false); setSaved(false); setLeft(30 * all.length);
  };

  const toggleTheme = (k) => setThemes((p) => (p.includes(k) ? (p.length > 1 ? p.filter((x) => x !== k) : p) : [...p, k]));
  const mm = String(Math.floor(Math.max(0, left) / 60)).padStart(2, "0");
  const ss = String(Math.max(0, left) % 60).padStart(2, "0");

  if (!qs) {
    return (
      <div>
        <p className="text-sm leading-relaxed mb-3" style={{ color: COLORS.inkSoft }}>
          Соберите тест сами: выберите темы и число заданий. На каждое отводится 30 секунд,
          общее время считается автоматически. Неверные варианты подбираются из той же темы
          и из близких по смыслу определений, поэтому угадать почти невозможно.
        </p>
        <p className="text-xs font-semibold uppercase tracking-wide mb-2" style={{ color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>Темы</p>
        <div className="grid grid-cols-2 gap-2 mb-4">
          {Object.keys(Q1_THEME_LABELS).map((k) => {
            const on = themes.includes(k);
            const n = Q1_TERM_BANK.filter((x) => x.th === k).length;
            return (
              <button key={k} onClick={() => toggleTheme(k)} className="text-left rounded-xl p-3"
                style={{ background: on ? COLORS.sageSoft : COLORS.surfaceSolid, border: `1px solid ${on ? COLORS.sage : COLORS.line}` }}>
                <p className="text-sm font-semibold" style={{ color: COLORS.ink }}>{Q1_THEME_LABELS[k]}</p>
                <p className="text-xs" style={{ color: COLORS.inkSoft }}>{n} терминов</p>
              </button>
            );
          })}
        </div>
        <p className="text-xs font-semibold uppercase tracking-wide mb-2" style={{ color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>Количество заданий</p>
        <div className="flex gap-2 flex-wrap mb-4">
          {[10, 20, 30, 50, 80].map((c) => (
            <button key={c} onClick={() => setCount(c)} className="px-4 py-2 rounded-full text-sm font-semibold"
              style={{ background: count === c ? COLORS.onyx : COLORS.surfaceSolid, color: count === c ? COLORS.onyxText : COLORS.inkSoft, border: `1px solid ${count === c ? COLORS.onyx : COLORS.line}` }}>
              {c}
            </button>
          ))}
          <span className="text-xs self-center" style={{ color: COLORS.inkSoft }}>
            доступно {pool.length} · время {Math.floor(count * 30 / 60)} мин
          </span>
        </div>
        <p className="text-xs font-semibold uppercase tracking-wide mb-2" style={{ color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>Направление</p>
        <div className="flex gap-2 flex-wrap mb-5">
          {[["term", "Определение → термин"], ["def", "Термин → определение"], ["mix", "Вперемешку"]].map(([k, label]) => (
            <button key={k} onClick={() => setDir(k)} className="px-3 py-2 rounded-full text-xs font-semibold"
              style={{ background: dir === k ? COLORS.blue : COLORS.surfaceSolid, color: dir === k ? "#FFF" : COLORS.inkSoft, border: `1px solid ${dir === k ? COLORS.blue : COLORS.line}` }}>
              {label}
            </button>
          ))}
        </div>
        <button onClick={() => setHard(!hard)} className="w-full text-left rounded-xl p-3 mb-4"
          style={{ background: hard ? COLORS.rustSoft : COLORS.surfaceSolid, border: `1px solid ${hard ? COLORS.rust : COLORS.line}` }}>
          <p className="text-sm font-semibold" style={{ color: COLORS.ink }}>Ловушечные вопросы {hard ? "включены" : "выключены"}</p>
          <p className="text-xs mt-0.5" style={{ color: COLORS.inkSoft }}>
            Около 40% заданий — на перевёрнутый знак, подмену индексов и смешение функций, а не на определения
          </p>
        </button>
        <button onClick={build} className="w-full py-3 rounded-xl text-sm font-semibold" style={{ background: COLORS.sage, color: "#FFF" }}>
          Начать тест
        </button>
      </div>
    );
  }

  const right = qs.filter((q, i) => ans[i] === q.a).length;
  const answered = Object.keys(ans).length;

  if (over || answered === qs.length) {
    const wrongList = qs.filter((q, i) => ans[i] !== q.a);
    if (!saved) {
      const th = {};
      qs.forEach((q, i) => {
        const k = q.it.th;
        if (!th[k]) th[k] = { right: 0, total: 0 };
        th[k].total += 1;
        if (ans[i] === q.a) th[k].right += 1;
      });
      setSaved(true);
      q1SaveAttempt({ kind: "drill", label: `Конструктор · ${qs.length} заданий`, score: right, max: qs.length, themes: th });
    }
    return (
      <div>
        <div className="rounded-2xl p-4 mb-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}` }}>
          <p className="text-lg font-bold" style={{ color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }}>{right} / {qs.length}</p>
          <p className="text-xs mt-1" style={{ color: COLORS.inkSoft }}>
            {left <= 0 ? "Время вышло" : "Тест завершён"} · {Math.round((right / qs.length) * 100)}% верных
          </p>
        </div>
        {wrongList.length > 0 && (
          <div className="mb-4">
            <p className="text-xs font-semibold uppercase tracking-wide mb-2" style={{ color: COLORS.rust, fontFamily: "'IBM Plex Mono', monospace" }}>Разбор ошибок</p>
            <div className="space-y-2">
              {wrongList.map((q, i) => (
                <div key={i} className="rounded-xl p-3" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
                  <p className="text-sm font-semibold" style={{ color: COLORS.ink }}>{q.it.t}</p>
                  {!q.hard && <p className="text-sm mt-1" style={{ color: COLORS.inkSoft }}>{q.it.d}</p>}
                  <p className="mt-1" style={{ fontSize: "11px", color: COLORS.inkSoft, opacity: 0.85 }}>{q.it.h}</p>
                </div>
              ))}
            </div>
          </div>
        )}
        <button onClick={() => setQs(null)} className="w-full py-3 rounded-xl text-sm font-semibold" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
          Собрать новый тест
        </button>
      </div>
    );
  }

  const q = qs[idx];
  const sel = ans[idx];
  return (
    <div>
      <div className="flex items-center justify-between rounded-xl px-4 py-3 mb-4" style={{ background: left <= 60 ? COLORS.rustSoft : COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
        <span className="text-xs" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{idx + 1} / {qs.length} · верно {right}</span>
        <span className="text-lg font-bold" style={{ color: left <= 60 ? COLORS.rust : COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }}>{mm}:{ss}</span>
      </div>
      <div className="rounded-2xl p-4 mb-3" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
        <p className="text-xs mb-2" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
          {q.asTerm ? "Какой термин соответствует определению?" : "Какое определение соответствует термину?"} · {Q1_THEME_LABELS[q.it.th]}
        </p>
        <p className="text-sm font-semibold leading-snug" style={{ color: COLORS.ink }}>{q.prompt}</p>
      </div>
      <div className="space-y-2">
        {q.opts.map((o, i) => {
          const showRight = sel !== undefined && i === q.a;
          const showWrong = sel === i && sel !== q.a;
          return (
            <button key={i} disabled={sel !== undefined} onClick={() => setAns((p) => ({ ...p, [idx]: i }))}
              className="w-full text-left px-3 py-2.5 rounded-xl text-sm"
              style={{ background: showRight ? COLORS.sageSoft : showWrong ? COLORS.rustSoft : COLORS.surfaceSolid,
                       border: `1px solid ${showRight ? COLORS.sage : showWrong ? COLORS.rust : COLORS.line}`, color: COLORS.ink }}>
              {o}
            </button>
          );
        })}
      </div>
      {sel !== undefined && (
        <div className="mt-3">
          <p className="text-xs leading-relaxed mb-3" style={{ color: COLORS.inkSoft }}>{q.it.h}</p>
          <button onClick={() => setIdx((v) => Math.min(v + 1, qs.length - 1))}
            disabled={idx === qs.length - 1 && answered < qs.length}
            className="w-full py-3 rounded-xl text-sm font-semibold" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
            {idx === qs.length - 1 ? "Завершить" : "Дальше"}
          </button>
        </div>
      )}
    </div>
  );
}


/* Тренажёр змейки: свободный ввод с проверкой сцепления букв и подсказками. */
function Q1SnakeTrainer() {
  const [variant, setVariant] = useState(null);
  const [ans, setAns] = useState({});
  const [hint, setHint] = useState({});
  const [left, setLeft] = useState(0);
  const [done, setDone] = useState(false);
  const [saved, setSaved] = useState(false);

  const set = variant === "A" ? Q1_SNAKE : variant === "B" ? Q1_SNAKE_B : [];

  useEffect(() => {
    if (!variant || done) return;
    if (left <= 0) { setDone(true); return; }
    const id = setTimeout(() => setLeft((v) => v - 1), 1000);
    return () => clearTimeout(id);
  }, [variant, left, done]);

  const okOf = (t) => q1Norm(ans[t.n]) === q1Norm(t.a) || (t.alt || []).some((v) => q1Norm(v) === q1Norm(ans[t.n]));
  const right = set.filter(okOf).length;

  useEffect(() => {
    if (!done || saved || !variant) return;
    setSaved(true);
    const th = {};
    set.forEach((t) => {
      const k = t.th || "micro";
      if (!th[k]) th[k] = { right: 0, total: 0 };
      th[k].total += 1;
      if (okOf(t)) th[k].right += 1;
    });
    q1SaveAttempt({ kind: "drill", label: `Змейка · вариант ${variant} · свободный ввод`, score: right * 2, max: set.length * 2, themes: th });
  }, [done]);

  const start = (v) => { setVariant(v); setAns({}); setHint({}); setDone(false); setSaved(false); setLeft(12 * 60); };
  const mm = String(Math.floor(Math.max(0, left) / 60)).padStart(2, "0");
  const ss = String(Math.max(0, left) % 60).padStart(2, "0");

  if (!variant) {
    return (
      <div>
        <p className="text-sm leading-relaxed mb-4" style={{ color: COLORS.inkSoft }}>
          Тридцать терминов вводятся руками, как на реальном туре: именительный падеж,
          единственное число, с маленькой буквы. Цепочка проверяется на лету — если ответ не
          начинается с нужной буквы, тренажёр об этом скажет, не раскрывая сам термин. Подсказку
          по каждому заданию можно открыть отдельно, но она отмечается в результате.
        </p>
        <div className="space-y-2">
          {["A", "B"].map((v) => (
            <button key={v} onClick={() => start(v)} className="w-full text-left rounded-2xl p-4"
              style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
              <p className="text-sm font-semibold" style={{ color: COLORS.ink }}>Цепочка {v}</p>
              <p className="text-xs mt-0.5" style={{ color: COLORS.inkSoft }}>30 терминов · 12 минут · 60 баллов</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  const usedHints = Object.keys(hint).length;

  return (
    <div>
      <div className="flex items-center justify-between rounded-xl px-4 py-3 mb-4 sticky top-0 z-10"
        style={{ background: !done && left <= 120 ? COLORS.rustSoft : COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
        <div>
          <p className="text-xs" style={{ color: COLORS.inkSoft }}>Цепочка {variant} · подсказок {usedHints}</p>
          <p className="text-lg font-bold" style={{ color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }}>
            {done ? `${right * 2} / 60` : `${mm}:${ss}`}
          </p>
        </div>
        <button onClick={() => (done ? setVariant(null) : setDone(true))}
          className="px-4 py-2 rounded-full text-xs font-semibold" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
          {done ? "Новая попытка" : "Завершить"}
        </button>
      </div>

      <div className="space-y-2">
        {set.map((t, i) => {
          const prev = i > 0 ? set[i - 1] : null;
          const needLetter = prev ? q1Norm(prev.a)[1] : null;
          const val = ans[t.n] || "";
          const firstLetter = q1Norm(val)[0];
          const chainBad = val && needLetter && firstLetter !== needLetter;
          const ok = done && okOf(t);
          return (
            <div key={t.n} className="rounded-xl p-3"
              style={{ background: COLORS.surfaceSolid, border: `1px solid ${done ? (ok ? COLORS.sage : COLORS.rust) + "66" : COLORS.line}` }}>
              <p className="text-sm mb-2" style={{ color: COLORS.ink }}>
                <b style={{ fontFamily: "'IBM Plex Mono', monospace" }}>{t.n}.</b> {t.q}
              </p>
              <input value={val} disabled={done}
                onChange={(e) => setAns((p) => ({ ...p, [t.n]: e.target.value }))}
                placeholder={needLetter ? `начинается на «${needLetter}»` : "ответ одним словом"}
                className="w-full px-3 py-2 rounded-lg text-sm"
                style={{ background: COLORS.paperDeep, border: `1px solid ${chainBad ? COLORS.rust : COLORS.line}`, color: COLORS.ink }} />
              <div className="flex items-center gap-2 mt-1.5 flex-wrap">
                {chainBad && !done && (
                  <span className="text-xs" style={{ color: COLORS.rust }}>связка не сходится: нужна буква «{needLetter}»</span>
                )}
                {!done && !hint[t.n] && (
                  <button onClick={() => setHint((p) => ({ ...p, [t.n]: true }))}
                    className="text-xs px-2 py-0.5 rounded-full" style={{ border: `1px solid ${COLORS.line}`, color: COLORS.inkSoft }}>
                    Подсказка
                  </button>
                )}
                {hint[t.n] && !done && (
                  <span className="text-xs" style={{ color: COLORS.amber }}>
                    {q1Norm(t.a).slice(0, 3)}… · {q1Norm(t.a).split(" ")[0].length} букв в первом слове
                  </span>
                )}
                {done && !ok && <span className="text-xs" style={{ color: COLORS.rust }}>верный ответ: {t.a}</span>}
              </div>
            </div>
          );
        })}
      </div>

      {!done && (
        <button onClick={() => setDone(true)} className="w-full py-3 rounded-xl text-sm font-semibold mt-4 mb-8"
          style={{ background: COLORS.sage, color: "#FFF" }}>
          Завершить и проверить
        </button>
      )}
    </div>
  );
}

function Q1Tur1Hub() {
  const [tab, setTab] = useState("exam");
  return (
    <div>
      <div className="flex gap-2 mb-4">
        {[["exam", "Пробный вариант"], ["snake", "Змейка"], ["drill", "Конструктор"], ["prog", "Прогресс"]].map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)} className="px-4 py-2 rounded-full text-xs font-semibold"
            style={{ background: tab === k ? COLORS.onyx : COLORS.surfaceSolid, color: tab === k ? COLORS.onyxText : COLORS.inkSoft, border: `1px solid ${tab === k ? COLORS.onyx : COLORS.line}` }}>
            {label}
          </button>
        ))}
      </div>
      {tab === "exam" ? <Q1MockExam /> : tab === "snake" ? <Q1SnakeTrainer /> : tab === "drill" ? <Q1TermDrill /> : <Q1Progress />}
    </div>
  );
}

