/* Нормализация ответа: убираем пробелы, запятые, приводим к нижнему регистру.
   Для multi-заданий сортируем цифры — порядок ввода не важен, как и на реальном ЕГЭ. */
function normalizeAnswer(raw, type) {
  const s = String(raw).toLowerCase().replace(/[\s,.\-;]/g, "").replace(/ё/g, "е");
  if (type === "multi") return s.split("").sort().join("");
  return s;
}

