            const lesson = SOCIAL_LESSONS_ALL.find((x) => x.key === openTopicKey);
            const title = theory?.title || "Тема " + openTopicKey;
            const pct = topicProgressPct(openTopicKey);
            const part2Task = findPart2ForTopic(openTopicKey);
            const cheatBullets = SOCIAL_TOPIC_CHEATS[openTopicKey] || lesson?.bullets || null;
            const curBlock = SOCIAL_CURRICULUM.find((b) => b.subtopics.some((st) => st.key === openTopicKey));
            const sibs = curBlock ? curBlock.subtopics : [];
            const sIdx = sibs.findIndex((st) => st.key === openTopicKey);
            const sPrev = sIdx > 0 ? sibs[sIdx - 1] : null;
