                <div key={label} className="rounded-xl p-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                  <div className="text-3xl font-bold" style={{ color, fontFamily: "'Figtree', sans-serif" }}>{value}</div>
                  <div className="text-xs mt-1" style={{ color: COLORS.inkSoft }}>{label}</div>
                </div>
