/* Реестр треков: добавление нового раздела — это одна строка здесь плюс сами данные (MAP/CARDS/TESTS). */
const TRACK_REGISTRY = {
  finlit: { tint: "amber", map: () => FINLIT_MAP, cards: () => FINLIT_CARDS, tests: () => [...FINLIT_TESTS, ...FINLIT_TESTS2], title: "Финансовая грамотность", storeKey: "fg" },
  biz: { tint: "rust", map: () => BIZ_MAP, cards: () => BIZ_CARDS, tests: () => [...BIZ_TESTS, ...BIZ_TESTS2, ...BIZ_TESTS3, ...BIZ_TESTS_TOUR1], tour1Tests: () => BIZ_TESTS_TOUR1, title: "Основы бизнеса", storeKey: "bz" },
  russian: { tint: "inkSoft", map: () => RUS_MAP, cards: () => [...RUS_CARDS, ...RUS_CARDS2, ...RUS_CARDS3], tests: () => [...RUS_TESTS, ...RUS_TESTS2, ...RUS_TESTS3, ...RUS_TESTS4, ...RUS_TESTS5, ...RUS_TESTS6, ...RUS_TESTS7, ...RUS_TESTS8, ...RUS_TESTS9, ...RUS_TESTS10, ...RUS_TESTS11], title: "Русский язык", storeKey: "ru" },
};

function TrackApp({ track, onBack, theme, onToggleTheme }) {
  const reg = TRACK_REGISTRY[track];
  const trackTint = COLORS[reg.tint] || COLORS.sage;
  const MAP = reg.map();
  const CARDS = reg.cards();
  const TESTS = reg.tests();
  const title = reg.title;
  const storeKey = reg.storeKey;

  const [tab, setTab] = useState("roadmap");
  const [openTopic, setOpenTopic] = useState(null);
  const [openLesson, setOpenLesson] = useState(null);
  const [checked, setChecked] = useState({});
  const [cardIdx, setCardIdx] = useState(0);
  const [showBack, setShowBack] = useState(false);
  const [cardTopic, setCardTopic] = useState(null);
  const [struggling, setStruggling] = useState({});
  const [reviewed, setReviewed] = useState({});
  const [cardShowMode, setCardShowMode] = useState("unreviewed");
  const [loaded, setLoaded] = useState(false);
  const [testIdx, setTestIdx] = useState(0);
  const [testTopic, setTestTopic] = useState(null);
  const [testResult, setTestResult] = useState(null);
  const [testStats, setTestStats] = useState({ right: 0, total: 0 });
  const testInputRef = React.useRef(null);
  const [examTaskNum, setExamTaskNum] = useState(1);
  const [examResult, setExamResult] = useState(null);
  const [examProgress, setExamProgress] = useState({});
  const examInputRef = React.useRef(null);
  const [essayPromptIdx, setEssayPromptIdx] = useState(0);
  const [essayChecklist, setEssayChecklist] = useState({});
  const [taskGridNum, setTaskGridNum] = useState(null);
  const [taskIdx, setTaskIdx] = useState(0);
  const [taskResult, setTaskResult] = useState(null);
  const [taskWordType, setTaskWordType] = useState(null);
  const [taskStatsAll, setTaskStatsAll] = useState({});
  const taskInputRef = React.useRef(null);

  /* ===== Режим «Отборочный этап · 1 тур»: отдельные плашки по темам + рандомизированный таймированный экзамен ===== */
  const [tour1View, setTour1View] = useState("plates"); // "plates" | <topicKey> | "exam-setup" | "exam-running" | "exam-finished"
  const [tour1DrillIdx, setTour1DrillIdx] = useState(0);
  const [tour1DrillResult, setTour1DrillResult] = useState(null);
  const [tour1DrillSelected, setTour1DrillSelected] = useState([]);
  const [examN, setExamN] = useState(20);
  const [examQueue, setExamQueue] = useState([]);
  const [examPos, setExamPos] = useState(0);
  const [examAnswers, setExamAnswers] = useState([]);
  const [examSelected, setExamSelected] = useState([]);
  const [examSecondsLeft, setExamSecondsLeft] = useState(0);
  const [examStopped, setExamStopped] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const [c, st, ts, rts, rv] = await Promise.allSettled([
          window.storage.get(storeKey + "-checked"),
          window.storage.get(storeKey + "-struggling"),
          window.storage.get(storeKey + "-teststats"),
          window.storage.get("ru-taskstats"),
          window.storage.get(storeKey + "-reviewed"),
        ]);
        if (c.status === "fulfilled" && c.value) setChecked(JSON.parse(c.value.value));
        if (st.status === "fulfilled" && st.value) setStruggling(JSON.parse(st.value.value));
        if (ts.status === "fulfilled" && ts.value) setTestStats(JSON.parse(ts.value.value));
        if (rts.status === "fulfilled" && rts.value) setTaskStatsAll(JSON.parse(rts.value.value));
        if (rv.status === "fulfilled" && rv.value) setReviewed(JSON.parse(rv.value.value));
      } catch (e) { /* первый запуск */ }
      setLoaded(true);
    })();
  }, [storeKey]);

  const persist = useCallback(async (k, v) => {
    try { await window.storage.set(storeKey + "-" + k, JSON.stringify(v), false); } catch (e) { /* не критично */ }
  }, [storeKey]);

  const allTopics = useMemo(() => MAP.flatMap((s) => s.topics), [MAP]);
  const allTopicsRef = React.useRef(allTopics);
  allTopicsRef.current = allTopics;
  const core = useMemo(() => MAP.filter((s) => (s.tier || 9) <= 2).flatMap((s) => s.topics), [MAP]);
  const bonus = useMemo(() => MAP.filter((s) => (s.tier || 9) > 2).flatMap((s) => s.topics), [MAP]);
  const coreDone = core.filter((t) => checked[t.key]).length;
  const bonusDone = bonus.filter((t) => checked[t.key]).length;
  const progress = core.length ? Math.round(((coreDone + bonusDone) / core.length) * 100) : 0;

  function toggle(key) {
    setChecked((p) => { const n = { ...p, [key]: !p[key] }; persist("checked", n); return n; });
  }

  const dueCards = useMemo(() => {
    let list = CARDS;
    if (cardTopic) list = list.filter((c) => c.topic === cardTopic);
    if (cardShowMode === "unreviewed") list = list.filter((c) => !reviewed[c.id]);
    return list;
  }, [CARDS, cardTopic, cardShowMode, reviewed]);
  const cur = dueCards.length ? dueCards[cardIdx % dueCards.length] : null;
  const hardCardsOnly = useMemo(() => CARDS.filter((c) => struggling[c.id]), [CARDS, struggling]);
  const hardTestsRaw = useMemo(() => TESTS.filter((t) => struggling["T" + t.id]), [TESTS, struggling]);
  const hardCards = useMemo(() => {
    const tests = hardTestsRaw.map((t) => ({
      id: "T" + t.id,
      topicLabel: "Тест · " + (allTopicsRef.current.find((x) => x.key === t.topic)?.label || t.topic),
      front: t.q + (t.opts.length ? "\n\n" + t.opts.map((o, i) => `${i + 1}) ${o}`).join("\n") : ""),
      back: `Ответ: ${t.a}\n\n${t.why}`,
    }));
    return [...hardCardsOnly, ...tests];
  }, [hardCardsOnly, hardTestsRaw]);
  /* Повторная попытка ответа прямо в «Бустерах»: выбор варианта(ов) на каждый сложный тест отдельно */
  const [boosterSelected, setBoosterSelected] = useState({});
  const [boosterRevealed, setBoosterRevealed] = useState({});

  /* Автопроверка теста: нормализуем ввод и сверяем с эталоном.
     Для multi порядок цифр не важен — как в бланке реального экзамена. */
  function checkTest(task) {
    const raw = testInputRef.current ? testInputRef.current.value : "";
    const ok = normalizeAnswer(raw, task.type) === normalizeAnswer(task.a, task.type) && raw.trim().length > 0;
    setTestResult({ ok, given: raw.trim() });
    setTestStats((p) => {
      const n = { right: p.right + (ok ? 1 : 0), total: p.total + 1 };
      persist("teststats", n);
      return n;
    });
    setStruggling((p) => {
      const n = { ...p };
      if (!ok) n["T" + task.id] = true; else delete n["T" + task.id];
      persist("struggling", n);
      return n;
    });
  }

  /* ===== Хелперы режима «Отборочный этап · 1 тур» ===== */
  const tour1Tests = reg.tour1Tests ? reg.tour1Tests() : [];
  const tour1TopicOrder = useMemo(
    () => allTopics.filter((t) => t.vp === "1 тур, 2026/2027").map((t) => t.key),
    [allTopics]
  );
  const tour1Label = (k) => allTopics.find((t) => t.key === k)?.label || k;

  function shuffled(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  /* Сборка очереди вопросов для экзамена: round-robin по темам в порядке карты,
     чтобы темы были представлены в примерно равной пропорции. */
  function buildExamQueue(n) {
    const byTopic = tour1TopicOrder
      .map((k) => shuffled(tour1Tests.filter((t) => t.topic === k)))
      .filter((arr) => arr.length > 0);
    const queue = [];
    let round = 0;
    while (queue.length < n && byTopic.some((arr) => arr[round])) {
      for (const arr of byTopic) {
        if (queue.length >= n) break;
        if (arr[round]) queue.push(arr[round]);
      }
      round++;
    }
    return queue;
  }

  function startExam(n) {
    const q = buildExamQueue(Math.min(n, tour1Tests.length));
    setExamQueue(q);
    setExamPos(0);
    setExamAnswers([]);
    setExamSelected([]);
    setExamSecondsLeft(q.length * 36);
    setExamStopped(false);
    setTour1View("exam-running");
  }

  function submitExamAnswer(skip, overrideSelected) {
    const cur = examQueue[examPos];
    if (!cur) return;
    const sel = overrideSelected !== undefined ? overrideSelected : examSelected;
    const given = skip ? "" : [...sel].sort((x, y) => x - y).join("");
    const ok = !skip && normalizeAnswer(given, "multi") === normalizeAnswer(cur.a, "multi");
    const nextAnswers = [...examAnswers, { id: cur.id, topic: cur.topic, ok, given }];
    setExamAnswers(nextAnswers);
    setExamSelected([]);
    /* Ошибки экзамена 1 тура уходят в общий пул «Бустеров», правильные ответы — убираются оттуда */
    setStruggling((p) => {
      const n = { ...p };
      if (!ok) n["T" + cur.id] = true; else delete n["T" + cur.id];
      persist("struggling", n);
      return n;
    });
    setTestStats((p) => {
      const n = { right: p.right + (ok ? 1 : 0), total: p.total + 1 };
      persist("teststats", n);
      return n;
    });
    if (examPos + 1 >= examQueue.length) {
      setTour1View("exam-finished");
    } else {
      setExamPos((p) => p + 1);
    }
  }

  function stopExamEarly() {
    setExamStopped(true);
    setTour1View("exam-finished");
  }

  /* Повторный ответ на сложный тест прямо в «Бустерах»: при верном ответе — сразу убираем из списка ошибок */
  function submitBoosterAnswer(test) {
    const sel = boosterSelected[test.id] || [];
    const given = [...sel].sort((x, y) => x - y).join("");
    const ok = normalizeAnswer(given, "multi") === normalizeAnswer(test.a, "multi");
    setBoosterRevealed((p) => ({ ...p, [test.id]: { ok, given } }));
    if (ok) {
      setStruggling((p) => {
        const n = { ...p };
        delete n["T" + test.id];
        persist("struggling", n);
        return n;
      });
    }
  }

  /* Общий обратный отсчёт на весь сеанс — как на реальном 1 туре (30 минут на 50 заданий, без возврата). */
  useEffect(() => {
    if (tour1View !== "exam-running") return;
    if (examSecondsLeft <= 0) {
      setTour1View("exam-finished");
      return;
    }
    const t = setTimeout(() => setExamSecondsLeft((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [tour1View, examSecondsLeft]);

  function gradeCard(card, ok) {
    setStruggling((p) => {
      const n = { ...p };
      if (!ok) n[card.id] = true; else delete n[card.id];
      persist("struggling", n);
      return n;
    });
    setReviewed((p) => {
      const n = { ...p };
      if (ok) n[card.id] = true; else delete n[card.id];
      persist("reviewed", n);
      return n;
    });
    setShowBack(false);
    setCardIdx((i) => i + 1);
  }

  /* Горячие клавиши в режиме карточек: пробел переворачивает,
     стрелки и цифры оценивают. Ускоряет тренировку в разы. */
  useEffect(() => {
    if (tab !== "cards") return;
    const onKey = (e) => {
      if (e.target && ["INPUT", "TEXTAREA"].includes(e.target.tagName)) return;
      const card = dueCards.length ? dueCards[cardIdx % dueCards.length] : null;
      if (!card) return;
      if (e.code === "Space" || e.key === "Enter") { e.preventDefault(); setShowBack((v) => !v); }
      else if (showBack && (e.key === "ArrowRight" || e.key === "2")) { e.preventDefault(); gradeCard(card, true); }
      else if (showBack && (e.key === "ArrowLeft" || e.key === "1")) { e.preventDefault(); gradeCard(card, false); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [tab, showBack, cardIdx, dueCards]);

  const open = openTopic ? allTopics.find((t) => t.key === openTopic) : null;
  const sec = open ? MAP.find((s) => s.topics.some((t) => t.key === open.key)) : null;
  const Lesson = openLesson ? DETAILED_THEORY_COMPONENTS[openLesson] : null;

  return (
    <div className="min-h-screen w-full" style={{
      background: pageBackground(trackTint),
      backgroundSize: PAGE_BG_SIZE,
      color: COLORS.ink, fontFamily: "'Figtree', ui-sans-serif, sans-serif" }}>
      <header className="max-w-5xl mx-auto px-6 pt-10 pb-2">
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div>
            <button onClick={onBack} className="text-xs mb-2 flex items-center gap-1" style={{ color: COLORS.inkSoft }}>
              <ArrowLeft size={13} /> На главный экран
            </button>
            <p className="text-xs tracking-widest uppercase" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>Высшая проба</p>
            <h1 className="text-3xl sm:text-4xl mt-1" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700 }}>{title}</h1>
          </div>
          <div className="flex items-center gap-2">
            <TopicSearch allTopics={allTopics} onGo={(key) => { setOpenTopic(key); setOpenLesson(null); setTab("roadmap"); }} />
            <SessionTimer />
            <button onClick={onToggleTheme} className="flex items-center gap-2 px-4 py-2.5 rounded-full" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
              {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
            </button>
          </div>
        </div>
        <TabsBar
          menu={[["progress", "Прогресс", Gauge], ["materials", "Материалы", BookOpen]]}
          modules={track === "russian"
            ? [["roadmap", "Темы", Map], ["cards", "Карточки", Brain], ["tests", "Тесты", ListChecks], ["exam", "Пробный вариант", PenLine], ["essay", "Сочинение", BookOpen], ["boosters", "Бустеры", Flame]]
            : [["roadmap", "Темы", Map], ["cards", "Карточки", Brain], ["tests", "Тесты", ListChecks], ["boosters", "Бустеры", Flame]]}
          active={tab}
          onPick={(k) => { setTab(k); setOpenTopic(null); setOpenLesson(null); setTestResult(null); if (k !== "cards") setCardTopic(null); }}
        />
      </header>

      <main className="max-w-5xl mx-auto px-6 pb-20 pt-6">
        {/* ---------- ТЕМЫ ---------- */}
        {tab === "roadmap" && !openTopic && !openLesson && (
          <div className="space-y-5">
            <div className="rounded-2xl p-6" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
              <p className="text-sm" style={{ color: COLORS.inkSoft }}>
                {allTopics.length} тем в {MAP.length} разделах. Разделы с пометкой «Задача N» разбирают
                конкретные задания заключительного этапа. Отмечай изученное галочкой — прогресс обновится сразу.
              </p>
              <p className="text-xs mt-2" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                изучено {coreDone + bonusDone} из {core.length} обязательных · прогресс {progress}%
              </p>
              <div className="flex items-center gap-3 mt-2 flex-wrap">
                <span className="flex items-center gap-1 text-xs" style={{ color: COLORS.inkSoft }}>
                  <span style={{ display: "inline-block", width: 8, height: 8, borderRadius: "50%", background: COLORS.sage }} /> максимально полный урок
                </span>
                <span className="flex items-center gap-1 text-xs" style={{ color: COLORS.inkSoft }}>
                  <span style={{ display: "inline-block", width: 8, height: 8, borderRadius: "50%", background: COLORS.amber }} /> расширенный
                </span>
                <span className="flex items-center gap-1 text-xs" style={{ color: COLORS.inkSoft }}>
                  <span style={{ display: "inline-block", width: 8, height: 8, borderRadius: "50%", background: COLORS.inkSoft }} /> базовый, требует доработки
                </span>
              </div>
            </div>
            {[...MAP].sort((a, b) => (a.tier || 9) - (b.tier || 9)).map((s) => {
              const done = s.topics.filter((t) => checked[t.key]).length;
              const all = done === s.topics.length;
              const isQualifying = s.id === "bz-qualifying";
              return (
                <div key={s.id} className="rounded-2xl p-5" style={{
                  background: all ? COLORS.sage
                    : isQualifying ? [
                        `radial-gradient(420px 220px at 96% 8%, ${COLORS.teal}26, transparent 62%)`,
                        `radial-gradient(460px 260px at 100% 95%, ${COLORS.sage}1E, transparent 65%)`,
                        COLORS.surface,
                      ].join(", ")
                    : COLORS.surface,
                  border: `1px solid ${all ? COLORS.sage : isQualifying ? COLORS.teal + "35" : COLORS.line}`,
                  boxShadow: (!all && isQualifying) ? `0 10px 28px -18px ${COLORS.teal}55` : "none",
                }}>
                  <div className="flex items-center gap-2 mb-1 flex-wrap">
                    {all && <CircleCheck size={16} color="#FFF" />}
                    {!all && isQualifying && (
                      <span style={{ display: "inline-block", width: 6, height: 6, borderRadius: "50%", background: `linear-gradient(135deg, ${COLORS.teal}, ${COLORS.sage})`, flexShrink: 0 }} />
                    )}
                    <p className="text-sm font-semibold" style={{ fontFamily: "'Figtree', sans-serif", fontSize: "1.05rem", color: all ? "#FFF" : COLORS.ink }}>{s.title}</p>
                    <span className="text-xs ml-auto" style={{ color: all ? "#FFFFFFCC" : COLORS.teal, fontFamily: "'IBM Plex Mono', monospace" }}>{done}/{s.topics.length}</span>
                  </div>
                  <p className="text-xs mb-3" style={{ color: all ? "#FFFFFFCC" : COLORS.inkSoft }}>{s.subtitle}</p>
                  <div className="space-y-0.5">
                    {[...s.topics].sort((a, b) => (a.isPractice ? 1 : 0) - (b.isPractice ? 1 : 0)).map((t) => {
                      const on = !!checked[t.key];
                      const hasLesson = !!DETAILED_THEORY_COMPONENTS[t.key];
                      return (
                        <div key={t.key} className="flex items-center gap-2 py-1.5" style={{ borderBottom: `1px solid ${all ? "#FFFFFF33" : COLORS.paperDeep}` }}>
                          <button onClick={() => toggle(t.key)} className="flex items-center justify-center rounded flex-shrink-0"
                            style={{ width: 18, height: 18, border: `1.5px solid ${on ? (all ? "#FFF" : COLORS.teal) : (all ? "#FFFFFF88" : COLORS.line)}`, background: on ? (all ? "#FFF" : COLORS.teal) : "transparent" }}>
                            {on && <Check size={12} color={all ? COLORS.sage : "#FFF"} />}
                          </button>
                          <span className="flex-shrink-0" style={{ width: 7 }}>
                            {hasLesson && <LessonDepthDot topicKey={t.key} />}
                          </span>
                          <button onClick={() => setOpenTopic(t.key)} className="flex items-center gap-1.5 text-left flex-1 min-w-0">
                            {t.isPractice && (
                              <span className="text-xs font-bold px-1.5 py-0.5 rounded flex-shrink-0" style={{ background: COLORS.teal, color: "#FFF", fontFamily: "'IBM Plex Mono', monospace" }}>ПРАКТИКУМ</span>
                            )}
                            <span className="text-sm truncate" style={{ color: all ? "#FFF" : COLORS.ink }}>{t.label}</span>
                            {!t.isPractice && t.prio === "S" && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0" style={{ background: all ? "#FFFFFF26" : COLORS.rustSoft, color: all ? "#FFF" : COLORS.rust }}>часто встречается</span>
                            )}
                            {!t.isPractice && t.prio === "A" && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0" style={{ background: all ? "#FFFFFF26" : COLORS.amberSoft, color: all ? "#FFF" : COLORS.amber }}>важная тема</span>
                            )}
                            {t.source === "own" && <span className="text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0" style={{ background: all ? "#FFFFFF26" : COLORS.blueSoft, color: all ? "#FFF" : COLORS.blue }}>моё объяснение</span>}
                            {hasLesson && <BookOpen size={12} color={all ? "#FFF" : COLORS.sage} style={{ flexShrink: 0 }} />}
                          </button>
                          <ChevronRight size={15} color={all ? "#FFFFFF88" : COLORS.inkSoft} style={{ flexShrink: 0 }} />
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* ---------- ДЕТАЛЬ ТЕМЫ ---------- */}
        {tab === "roadmap" && openTopic && !openLesson && open && (
          <div>
            <button onClick={() => setOpenTopic(null)} className="flex items-center gap-1 text-sm mb-4" style={{ color: COLORS.inkSoft }}>
              <ArrowLeft size={15} /> К карте тем
            </button>
            <div className="rounded-2xl p-6 sm:p-8" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
              <p className="text-xs mb-2" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{sec?.title}</p>
              <h3 className="text-xl mb-3" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700 }}>{open.label}</h3>
              <div className="flex gap-2 flex-wrap mb-5 items-center">
                <Pill tone="blue">{LEVELS[open.level].label}</Pill>
                <Pill tone={PRIO[open.prio].color}>{PRIO[open.prio].label}</Pill>
                {open.vp && <Pill tone="amber">{open.vp}</Pill>}
                <button onClick={() => toggle(open.key)} className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-full ml-auto"
                  style={{ background: checked[open.key] ? COLORS.teal : COLORS.paperDeep, color: checked[open.key] ? "#FFF" : COLORS.inkSoft }}>
                  {checked[open.key] ? <Check size={13} /> : null} {checked[open.key] ? "Изучено" : "Отметить изученным"}
                </button>
              </div>
              {open.source === "own" && (
                <div className="rounded-2xl p-3 mb-4 text-sm" style={{ background: COLORS.blueSoft, color: COLORS.ink }}>
                  ⓘ В присланных материалах теории по этой теме не было — объяснение написано мной
                  на основе действующего законодательства и стандартных учебных источников.
                </div>
              )}
              {open.formulas && (<><p className="text-xs font-semibold mb-2 uppercase tracking-wide" style={{ color: COLORS.teal, fontFamily: "'IBM Plex Mono', monospace" }}>Формулы и нормы</p>
                <div className="rounded-2xl p-4 mb-5" style={{ background: COLORS.amberSoft, border: `1px dashed ${COLORS.amber}` }}>
                  {open.formulas.map((f, i) => <p key={i} className="text-sm mb-1.5" style={{ fontFamily: "'IBM Plex Mono', monospace" }}>{f}</p>)}
                </div></>)}
              {open.methods && (<><p className="text-xs font-semibold mb-2 uppercase tracking-wide" style={{ color: COLORS.sage, fontFamily: "'IBM Plex Mono', monospace" }}>Что нужно знать</p>
                <ul className="space-y-2 mb-5">{open.methods.map((m, i) => <li key={i} className="text-sm leading-relaxed pl-4 relative" style={{ color: COLORS.inkSoft }}><span className="absolute left-0" style={{ color: COLORS.sage }}>→</span>{m}</li>)}</ul></>)}
              {open.traps && (<><p className="text-xs font-semibold mb-2 uppercase tracking-wide" style={{ color: COLORS.rust, fontFamily: "'IBM Plex Mono', monospace" }}>Ловушки</p>
                <div className="space-y-2 mb-5">{open.traps.map((t, i) => <div key={i} className="rounded-2xl p-3 text-sm" style={{ background: COLORS.rustSoft }}>⚠ {t}</div>)}</div></>)}
              <div className="flex gap-2 flex-wrap pt-4" style={{ borderTop: `1px solid ${COLORS.line}` }}>
                {DETAILED_THEORY_COMPONENTS[open.key] && (
                  <button onClick={() => setOpenLesson(open.key)} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-semibold" style={{ background: COLORS.blue, color: "#FFF" }}>
                    <BookOpen size={15} /> Полный урок
                  </button>
                )}
                {CARDS.some((c) => c.topic === open.key) && (
                  <button onClick={() => { setCardTopic(open.key); setTab("cards"); setCardIdx(0); setShowBack(false); }} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF" }}>
                    <Brain size={15} /> Карточки ({CARDS.filter((c) => c.topic === open.key).length})
                  </button>
                )}
              </div>
            </div>
          </div>
        )}

        {/* ---------- УРОК ---------- */}
        {tab === "roadmap" && openLesson && Lesson && (
          <div>
            <button onClick={() => setOpenLesson(null)} className="flex items-center gap-1 text-sm mb-4" style={{ color: COLORS.inkSoft }}>
              <ArrowLeft size={15} /> К теме
            </button>
            <div className="rounded-2xl p-6 sm:p-8" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
              <Lesson />
            </div>
          </div>
        )}

        {/* ---------- КАРТОЧКИ ---------- */}
        {tab === "cards" && (() => {
          const scopeCards = cardTopic ? CARDS.filter((c) => c.topic === cardTopic) : CARDS;
          const reviewedCount = scopeCards.filter((c) => reviewed[c.id]).length;
          const cardOpenTopic = () => { setOpenTopic(cur.topic); setTab("roadmap"); };
          return (
          <div>
            <div className="flex gap-1.5 flex-wrap mb-3 items-center">
              <button onClick={() => { setCardTopic(null); setCardIdx(0); setShowBack(false); }}
                className="text-xs font-medium px-3 py-1.5 rounded-2xl"
                style={{ background: !cardTopic ? COLORS.onyx : COLORS.paperDeep, color: !cardTopic ? COLORS.onyxText : COLORS.inkSoft }}>
                Все ({CARDS.length})
              </button>
              {allTopics.filter((t) => CARDS.some((c) => c.topic === t.key)).map((t) => (
                <button key={t.key} onClick={() => { setCardTopic(t.key); setCardIdx(0); setShowBack(false); }}
                  className="text-xs font-medium px-2.5 py-1.5 rounded-2xl"
                  style={{ background: cardTopic === t.key ? COLORS.teal : COLORS.paperDeep, color: cardTopic === t.key ? "#FFF" : COLORS.inkSoft }}>
                  {t.label.length > 26 ? t.label.slice(0, 26) + "…" : t.label}
                </button>
              ))}
            </div>
            <div className="flex items-center gap-3 mb-4 flex-wrap">
              <div className="flex gap-1 p-0.5 rounded-2xl" style={{ background: COLORS.paperDeep }}>
                <button onClick={() => { setCardShowMode("unreviewed"); setCardIdx(0); setShowBack(false); }}
                  className="text-xs font-medium px-2.5 py-1 rounded-md"
                  style={{ background: cardShowMode === "unreviewed" ? COLORS.surfaceSolid : "transparent", color: cardShowMode === "unreviewed" ? COLORS.ink : COLORS.inkSoft }}>
                  Не пройдено ({scopeCards.length - reviewedCount})
                </button>
                <button onClick={() => { setCardShowMode("all"); setCardIdx(0); setShowBack(false); }}
                  className="text-xs font-medium px-2.5 py-1 rounded-md"
                  style={{ background: cardShowMode === "all" ? COLORS.surfaceSolid : "transparent", color: cardShowMode === "all" ? COLORS.ink : COLORS.inkSoft }}>
                  Все ({scopeCards.length})
                </button>
              </div>
              <span className="text-xs" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                пройдено {reviewedCount}/{scopeCards.length}
              </span>
            </div>
            {!cur ? (
              <div className="rounded-2xl p-10 text-center ms-rise" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                {cardShowMode === "unreviewed" && scopeCards.length > 0 ? (
                  <>
                    <div className="mx-auto mb-3" style={{ position: "relative", width: 48, height: 48 }}>
                      <div className="ms-halo" style={{ position: "absolute", inset: 0, borderRadius: 999, background: COLORS.sage, opacity: .25 }} />
                      <div style={{ position: "relative", width: 48, height: 48, borderRadius: 999, background: COLORS.sageSoft, display: "flex", alignItems: "center", justifyContent: "center" }}>
                        <CircleCheck size={22} color={COLORS.sage} />
                      </div>
                    </div>
                    <p className="font-medium" style={{ fontFamily: "'Figtree', sans-serif", fontSize: "1.2rem" }}>Все карточки пройдены</p>
                    <button onClick={() => setCardShowMode("all")} className="text-xs font-semibold px-3 py-1.5 rounded-full mt-3" style={{ background: COLORS.teal, color: "#FFF" }}>Повторить все ещё раз</button>
                  </>
                ) : (
                  <p style={{ color: COLORS.inkSoft }}>Карточек по этой теме пока нет.</p>
                )}
              </div>
            ) : (
              <div>
                <div className="text-xs mb-3" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{(cardIdx % dueCards.length) + 1} / {dueCards.length}</div>
                <div key={cur.id} className="p-8 min-h-[200px] cursor-pointer ms-rise" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, borderRadius: 28 }} onClick={() => setShowBack((v) => !v)}>
                  <div className="flex items-center gap-2 flex-wrap">
                    <Pill tone="teal">{cur.topicLabel}</Pill>
                    {reviewed[cur.id] && <Pill tone="sage">пройдено</Pill>}
                  </div>
                  <p className="mt-4 text-lg leading-relaxed" style={{ fontFamily: "'Figtree', sans-serif" }}>{cur.front}</p>
                  {showBack && <p className="mt-4 pt-4 text-base leading-relaxed" style={{ borderTop: `1px dashed ${COLORS.line}`, color: COLORS.inkSoft }}>{cur.back}</p>}
                  {!showBack && <p className="text-xs mt-4" style={{ color: COLORS.inkSoft }}>Нажми, чтобы увидеть ответ</p>}
                </div>
                {showBack && (
                  <div className="mt-4">
                    <div className="grid grid-cols-2 gap-2">
                      <button onClick={() => gradeCard(cur, false)} className="py-3 rounded-full text-sm font-semibold" style={{ background: COLORS.rust, color: "#FFF" }}>Неправильно <span style={{ opacity: 0.6 }}>←</span></button>
                      <button onClick={() => gradeCard(cur, true)} className="py-3 rounded-full text-sm font-semibold" style={{ background: COLORS.sage, color: "#FFF" }}>Правильно <span style={{ opacity: 0.6 }}>→</span></button>
                    </div>
                    <div className="flex items-center justify-between mt-2 flex-wrap gap-2">
                      <p className="text-xs" style={{ color: COLORS.inkSoft }}>
                        Клавиши: пробел — перевернуть, ← неправильно, → правильно
                      </p>
                      {allTopics.some((t) => t.key === cur.topic) && (
                        <button onClick={cardOpenTopic} className="text-xs font-medium" style={{ color: COLORS.blue }}>
                          Открыть правило в теме →
                        </button>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
          );
        })()}

        {/* ---------- ОТБОРОЧНЫЙ ЭТАП · 1 ТУР — отдельный раздел с плашками по темам и экзаменационным режимом ---------- */}
        {tab === "tests" && track !== "russian" && tour1Tests.length > 0 && (() => {
          const doneTopics = tour1TopicOrder.map((k) => ({
            key: k,
            label: tour1Label(k),
            count: tour1Tests.filter((t) => t.topic === k).length,
          }));

          if (tour1View === "plates") {
            return (
              <div className="mb-6 rounded-2xl p-5" style={{
                background: [
                  `radial-gradient(420px 220px at 96% 8%, ${COLORS.teal}26, transparent 62%)`,
                  `radial-gradient(460px 260px at 100% 95%, ${COLORS.sage}1E, transparent 65%)`,
                  COLORS.surface,
                ].join(", "),
                border: `1px solid ${COLORS.teal}35`,
                boxShadow: `0 10px 28px -18px ${COLORS.teal}55`,
              }}>
                <div className="flex items-center justify-between flex-wrap gap-3 mb-4">
                  <div>
                    <p className="text-xs tracking-widest uppercase" style={{ color: COLORS.teal, fontFamily: "'IBM Plex Mono', monospace" }}>Отборочный этап · 1 тур 2026/2027</p>
                    <p className="text-xs mt-1" style={{ color: COLORS.inkSoft }}>{tour1Tests.length} заданий закрытого типа по {doneTopics.filter((t) => t.count > 0).length} темам — как в реальном варианте</p>
                  </div>
                  <button onClick={() => setTour1View("exam-setup")}
                    className="px-6 py-3 rounded-xl text-sm font-bold flex items-center gap-2 flex-shrink-0"
                    style={{ background: `linear-gradient(135deg, ${COLORS.teal}, ${COLORS.sage})`, color: "#FFF", boxShadow: `0 8px 20px -8px ${COLORS.teal}` }}>
                    <Zap size={16} /> Старт: экзамен на время
                  </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {doneTopics.map((t) => (
                    <button key={t.key} disabled={t.count === 0}
                      onClick={() => { setTour1View(t.key); setTour1DrillIdx(0); setTour1DrillResult(null); setTour1DrillSelected([]); }}
                      className="flex items-center justify-between gap-2 px-3.5 py-2.5 rounded-xl text-left"
                      style={{ background: t.count > 0 ? COLORS.surfaceSolid : COLORS.paperDeep, border: `1px solid ${COLORS.line}`, opacity: t.count > 0 ? 1 : 0.45, cursor: t.count > 0 ? "pointer" : "default" }}>
                      <span className="text-sm" style={{ color: COLORS.ink }}>{t.label}</span>
                      <span className="flex items-center gap-1.5 flex-shrink-0">
                        <span className="text-xs" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{t.count || "—"}</span>
                        {t.count > 0 && <ChevronRight size={14} color={COLORS.inkSoft} />}
                      </span>
                    </button>
                  ))}
                </div>
              </div>
            );
          }

          if (tour1View === "exam-setup") {
            const maxN = tour1Tests.length;
            const presets = [10, 20, 30, 50].filter((p) => p <= maxN);
            return (
              <div className="mb-6 rounded-2xl p-6" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}` }}>
                <button onClick={() => setTour1View("plates")} className="text-xs mb-4 flex items-center gap-1" style={{ color: COLORS.inkSoft }}>
                  <ArrowLeft size={13} /> Назад к темам
                </button>
                <p className="text-lg font-semibold mb-1" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>Экзамен на время</p>
                <p className="text-xs mb-5" style={{ color: COLORS.inkSoft }}>
                  Вопросы случайно берутся из всех тем 1 тура в примерно равной пропорции. На каждое задание — 36 секунд
                  (как в реальном варианте: 50 заданий за 30 минут), общий таймер запускается один раз на всю сессию.
                  Правильность ответа не показывается по ходу теста — только в конце. Вернуться к пройденному вопросу нельзя.
                </p>
                <p className="text-xs mb-2" style={{ color: COLORS.inkSoft }}>Сколько заданий? (доступно всего {maxN})</p>
                <div className="flex gap-2 flex-wrap mb-4">
                  {presets.map((p) => (
                    <button key={p} onClick={() => setExamN(p)}
                      className="px-4 py-2 rounded-lg text-sm font-semibold"
                      style={{ background: examN === p ? COLORS.teal : COLORS.paperDeep, color: examN === p ? "#FFF" : COLORS.inkSoft }}>
                      {p}
                    </button>
                  ))}
                  <input type="number" min={1} max={maxN} value={examN}
                    onChange={(e) => setExamN(Math.max(1, Math.min(maxN, Number(e.target.value) || 1)))}
                    className="w-24 px-3 py-2 rounded-lg text-sm text-center"
                    style={{ background: COLORS.paperDeep, border: `1px solid ${COLORS.line}`, color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }} />
                </div>
                <p className="text-xs mb-5" style={{ color: COLORS.teal, fontFamily: "'IBM Plex Mono', monospace" }}>
                  Таймер: {Math.floor(examN * 36 / 60)} мин {examN * 36 % 60} сек на {examN} заданий
                </p>
                <button onClick={() => startExam(examN)}
                  className="w-full py-3.5 rounded-xl text-sm font-bold"
                  style={{ background: `linear-gradient(135deg, ${COLORS.teal}, ${COLORS.sage})`, color: "#FFF" }}>
                  Начать экзамен →
                </button>
              </div>
            );
          }

          if (tour1View === "exam-running") {
            const cur = examQueue[examPos];
            const mm = String(Math.floor(examSecondsLeft / 60)).padStart(2, "0");
            const ss = String(examSecondsLeft % 60).padStart(2, "0");
            const urgent = examSecondsLeft <= 30;
            const isSingle = cur && cur.a.length === 1;
            return (
              <div className="mb-6 rounded-2xl p-6" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
                <div className="flex items-center justify-between mb-4">
                  <span className="text-xs" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                    Задание {examPos + 1} / {examQueue.length}
                  </span>
                  <span className="text-lg font-bold px-3 py-1 rounded-lg" style={{ color: urgent ? "#FFF" : COLORS.ink, background: urgent ? COLORS.rust : COLORS.paperDeep, fontFamily: "'IBM Plex Mono', monospace" }}>
                    {mm}:{ss}
                  </span>
                  <button onClick={stopExamEarly} className="text-xs px-3 py-1.5 rounded-lg" style={{ color: COLORS.rust, background: COLORS.rustSoft }}>
                    Завершить досрочно
                  </button>
                </div>
                {cur && (
                  <>
                    <Pill tone="teal">{tour1Label(cur.topic)}</Pill>
                    <p className="text-sm leading-relaxed my-3" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>{cur.q}</p>
                    <div className="space-y-2 mb-4">
                      {cur.opts.map((o, i) => {
                        const num = i + 1;
                        const on = examSelected.includes(num);
                        return (
                          <button key={i}
                            onClick={() => {
                              if (isSingle) { setExamSelected([num]); setTimeout(() => submitExamAnswer(false, [num]), 120); }
                              else setExamSelected((p) => on ? p.filter((x) => x !== num) : [...p, num]);
                            }}
                            className="w-full text-left px-4 py-2.5 rounded-lg text-sm flex gap-2"
                            style={{ background: on ? COLORS.tealSoft : COLORS.paperDeep, border: `1.5px solid ${on ? COLORS.teal : "transparent"}`, color: COLORS.ink }}>
                            <span className="font-semibold flex-shrink-0" style={{ color: COLORS.blue, fontFamily: "'IBM Plex Mono', monospace" }}>{num})</span>
                            <span>{o}</span>
                          </button>
                        );
                      })}
                    </div>
                    {!isSingle && (
                      <div className="flex gap-2">
                        <button onClick={() => submitExamAnswer(true)} className="px-4 py-2.5 rounded-lg text-sm" style={{ color: COLORS.inkSoft, background: COLORS.paperDeep }}>
                          Пропустить
                        </button>
                        <button onClick={() => submitExamAnswer(false)} disabled={examSelected.length === 0}
                          className="flex-1 py-2.5 rounded-xl text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF", opacity: examSelected.length === 0 ? 0.5 : 1 }}>
                          Ответить →
                        </button>
                      </div>
                    )}
                  </>
                )}
              </div>
            );
          }

          if (tour1View === "exam-finished") {
            const total = examAnswers.length;
            const right = examAnswers.filter((a) => a.ok).length;
            const pct = total ? Math.round((right / total) * 100) : 0;
            const byTopic = {};
            examAnswers.forEach((a) => {
              byTopic[a.topic] = byTopic[a.topic] || { right: 0, total: 0 };
              byTopic[a.topic].total++;
              if (a.ok) byTopic[a.topic].right++;
            });
            return (
              <div className="mb-6 rounded-2xl p-6" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}` }}>
                <p className="text-xs mb-1" style={{ color: COLORS.inkSoft }}>{examStopped ? "Тест остановлен досрочно" : examSecondsLeft <= 0 ? "Время вышло" : "Тест завершён"}</p>
                <p className="text-4xl font-bold mb-1" style={{ color: toneForValue(pct), fontFamily: "'IBM Plex Mono', monospace" }}>{right}/{total}</p>
                <p className="text-sm mb-5" style={{ color: COLORS.inkSoft }}>{pct}% правильных ответов</p>
                <div className="space-y-1.5 mb-5">
                  {Object.entries(byTopic).map(([k, v]) => (
                    <div key={k} className="flex items-center justify-between text-xs px-3 py-2 rounded-lg" style={{ background: COLORS.paperDeep }}>
                      <span style={{ color: COLORS.ink }}>{tour1Label(k)}</span>
                      <span style={{ color: toneForValue(Math.round(v.right / v.total * 100)), fontFamily: "'IBM Plex Mono', monospace" }}>{v.right}/{v.total}</span>
                    </div>
                  ))}
                </div>
                <details className="mb-5">
                  <summary className="text-xs cursor-pointer" style={{ color: COLORS.teal }}>Разбор всех заданий</summary>
                  <div className="mt-3 space-y-3">
                    {examQueue.map((q, i) => {
                      const ans = examAnswers[i];
                      if (!ans) return null;
                      return (
                        <div key={q.id} className="rounded-lg p-3" style={{ background: ans.ok ? COLORS.sageSoft : COLORS.rustSoft }}>
                          <p className="text-xs font-semibold mb-1" style={{ color: ans.ok ? COLORS.sage : COLORS.rust }}>
                            {ans.ok ? "✓ Верно" : `✕ Твой ответ: ${ans.given || "пропущено"} · Правильный: ${q.a}`}
                          </p>
                          <p className="text-sm mb-1" style={{ color: COLORS.ink }}>{q.q}</p>
                          <p className="text-xs" style={{ color: COLORS.inkSoft }}>{q.why}</p>
                        </div>
                      );
                    })}
                  </div>
                </details>
                <div className="flex gap-2">
                  <button onClick={() => setTour1View("exam-setup")} className="flex-1 py-2.5 rounded-xl text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF" }}>
                    Пройти ещё раз
                  </button>
                  <button onClick={() => setTour1View("plates")} className="flex-1 py-2.5 rounded-xl text-sm font-semibold" style={{ background: COLORS.paperDeep, color: COLORS.inkSoft }}>
                    Назад к темам
                  </button>
                </div>
              </div>
            );
          }

          /* Дрилдаун в конкретную тему: практика с мгновенной проверкой (не экзаменационный режим) */
          const drillPool = tour1Tests.filter((t) => t.topic === tour1View);
          const drillCur = drillPool.length ? drillPool[tour1DrillIdx % drillPool.length] : null;
          if (!drillCur) return null;
          const drillIsSingle = drillCur.a.length === 1;
          return (
            <div className="mb-6 rounded-2xl p-6" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
              <button onClick={() => setTour1View("plates")} className="text-xs mb-3 flex items-center gap-1" style={{ color: COLORS.inkSoft }}>
                <ArrowLeft size={13} /> Назад к темам 1 тура
              </button>
              <div className="flex items-center justify-between mb-2">
                <Pill tone="teal">{tour1Label(tour1View)}</Pill>
                <span className="text-xs" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{(tour1DrillIdx % drillPool.length) + 1} / {drillPool.length}</span>
              </div>
              <p className="text-sm leading-relaxed my-3" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>{drillCur.q}</p>
              {!tour1DrillResult ? (
                <>
                  <div className="space-y-2 mb-3">
                    {drillCur.opts.map((o, i) => {
                      const num = i + 1;
                      const on = tour1DrillSelected.includes(num);
                      return (
                        <button key={i}
                          onClick={() => {
                            if (drillIsSingle) {
                              const ok = String(num) === drillCur.a;
                              setTour1DrillResult({ ok, given: String(num) });
                              setStruggling((p) => {
                                const n = { ...p };
                                if (!ok) n["T" + drillCur.id] = true; else delete n["T" + drillCur.id];
                                persist("struggling", n);
                                return n;
                              });
                            } else {
                              setTour1DrillSelected((p) => on ? p.filter((x) => x !== num) : [...p, num]);
                            }
                          }}
                          className="w-full text-left px-4 py-2.5 rounded-lg text-sm flex gap-2"
                          style={{ background: on ? COLORS.tealSoft : COLORS.paperDeep, border: `1.5px solid ${on ? COLORS.teal : "transparent"}`, color: COLORS.ink }}>
                          <span className="font-semibold flex-shrink-0" style={{ color: COLORS.blue, fontFamily: "'IBM Plex Mono', monospace" }}>{num})</span>
                          <span>{o}</span>
                        </button>
                      );
                    })}
                  </div>
                  {!drillIsSingle && (
                    <button onClick={() => {
                      const given = [...tour1DrillSelected].sort((x, y) => x - y).join("");
                      const ok = normalizeAnswer(given, "multi") === normalizeAnswer(drillCur.a, "multi");
                      setTour1DrillResult({ ok, given });
                      setStruggling((p) => {
                        const n = { ...p };
                        if (!ok) n["T" + drillCur.id] = true; else delete n["T" + drillCur.id];
                        persist("struggling", n);
                        return n;
                      });
                    }} disabled={tour1DrillSelected.length === 0}
                      className="w-full py-2.5 rounded-xl text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF", opacity: tour1DrillSelected.length === 0 ? 0.5 : 1 }}>
                      Ответить
                    </button>
                  )}
                </>
              ) : (
                <div>
                  <div className="rounded-lg p-4 mb-3" style={{ background: tour1DrillResult.ok ? COLORS.sageSoft : COLORS.rustSoft }}>
                    <p className="text-sm font-semibold mb-1" style={{ color: tour1DrillResult.ok ? COLORS.sage : COLORS.rust }}>
                      {tour1DrillResult.ok ? "✓ Верно" : `✕ Неверно. Твой ответ: ${tour1DrillResult.given || "—"} · Правильный: ${drillCur.a}`}
                    </p>
                    <p className="text-sm leading-relaxed mt-2" style={{ color: COLORS.ink }}>{drillCur.why}</p>
                  </div>
                  <button onClick={() => { setTour1DrillIdx((i) => i + 1); setTour1DrillResult(null); setTour1DrillSelected([]); }}
                    className="w-full py-2.5 rounded-xl text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF" }}>
                    Следующее задание →
                  </button>
                </div>
              )}
            </div>
          );
        })()}

        {/* ---------- ТЕСТЫ (остальные, не из 1 тура) ---------- */}
        {tab === "tests" && track !== "russian" && (() => {
          const tour1Ids = new Set(tour1Tests.map((t) => t.id));
          const basePool = TESTS.filter((t) => !tour1Ids.has(t.id));
          const pool = testTopic ? basePool.filter((t) => t.topic === testTopic) : basePool;
          const cur = pool.length ? pool[testIdx % pool.length] : null;
          const acc = testStats.total ? Math.round((testStats.right / testStats.total) * 100) : null;
          const topicLabel = (k) => allTopics.find((t) => t.key === k)?.label || k;
          if (!cur) {
            return (
              <div className="rounded-2xl p-10 text-center" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <p style={{ color: COLORS.inkSoft }}>По этой теме тестов пока нет.</p>
              </div>
            );
          }
          return (
            <div>
              <div className="rounded-xl p-4 mb-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <p className="text-xs mb-3" style={{ color: COLORS.inkSoft }}>
                  Задания в формате отборочного этапа. Ответ вводится цифрами без пробелов;
                  для заданий с выбором нескольких верных порядок цифр не важен.
                  Ошибки автоматически попадают в «Бустеры».
                </p>
                <div className="flex gap-1.5 flex-wrap items-center">
                  <button onClick={() => { setTestTopic(null); setTestIdx(0); setTestResult(null); }}
                    className="text-xs font-medium px-3 py-1.5 rounded-2xl"
                    style={{ background: !testTopic ? COLORS.onyx : COLORS.paperDeep, color: !testTopic ? COLORS.onyxText : COLORS.inkSoft }}>
                    Все ({TESTS.length})
                  </button>
                  {[...new Set(TESTS.map((t) => t.topic))].map((k) => {
                    const n = TESTS.filter((t) => t.topic === k).length;
                    const on = testTopic === k;
                    const lbl = topicLabel(k);
                    return (
                      <button key={k} onClick={() => { setTestTopic(on ? null : k); setTestIdx(0); setTestResult(null); }}
                        title={lbl}
                        className="text-xs font-medium px-2.5 py-1.5 rounded-2xl"
                        style={{ background: on ? COLORS.teal : COLORS.paperDeep, color: on ? "#FFF" : COLORS.inkSoft }}>
                        {lbl.length > 24 ? lbl.slice(0, 24) + "…" : lbl} · {n}
                      </button>
                    );
                  })}
                  {acc !== null && (
                    <span className="text-xs ml-auto" style={{ color: toneForValue(acc), fontFamily: "'IBM Plex Mono', monospace" }}>
                      точность {acc}% ({testStats.right}/{testStats.total})
                    </span>
                  )}
                </div>
              </div>

              <div className="text-xs mb-2" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                {(testIdx % pool.length) + 1} / {pool.length}
              </div>

              <div className="rounded-2xl p-6" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <div className="flex gap-2 flex-wrap mb-3">
                  <Pill tone="teal">{topicLabel(cur.topic)}</Pill>
                  <Pill tone="blue">{cur.type === "multi" ? "выбор нескольких" : "числовой ответ"}</Pill>
                </div>
                <p className="text-sm leading-relaxed mb-3" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>{cur.q}</p>
                {cur.opts.length > 0 && (
                  <ol className="mb-4 space-y-1.5" style={{ listStyle: "none", padding: 0 }}>
                    {cur.opts.map((o, i) => (
                      <li key={i} className="text-sm flex gap-2" style={{ color: COLORS.inkSoft }}>
                        <span className="flex-shrink-0 font-semibold" style={{ color: COLORS.blue, fontFamily: "'IBM Plex Mono', monospace" }}>{i + 1})</span>
                        <span>{o}</span>
                      </li>
                    ))}
                  </ol>
                )}
                {!testResult ? (
                  <div>
                    <p className="text-xs mb-2" style={{ color: COLORS.inkSoft }}>Твой ответ:</p>
                    <div className="flex gap-2">
                      <input key={cur.id} ref={testInputRef} defaultValue=""
                        onKeyDown={(e) => { if (e.key === "Enter") checkTest(cur); }}
                        placeholder={cur.type === "multi" ? "например 135" : "число"}
                        className="flex-1 px-3 py-2.5 rounded-2xl text-sm"
                        style={{ background: COLORS.paperDeep, border: `1px solid ${COLORS.line}`, color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }} />
                      <button onClick={() => checkTest(cur)}
                        className="px-5 py-2.5 rounded-full text-sm font-semibold"
                        style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
                        Проверить
                      </button>
                    </div>
                  </div>
                ) : (
                  <div>
                    <div className="rounded-2xl p-4 mb-3" style={{ background: testResult.ok ? COLORS.sageSoft : COLORS.rustSoft }}>
                      <p className="text-sm font-semibold mb-1" style={{ color: testResult.ok ? COLORS.sage : COLORS.rust }}>
                        {testResult.ok ? "✓ Верно" : `✕ Неверно. Твой ответ: ${testResult.given || "—"} · Правильный: ${cur.a}`}
                      </p>
                      <p className="text-sm leading-relaxed mt-2" style={{ color: COLORS.ink }}>{cur.why}</p>
                    </div>
                    <button onClick={() => { setTestIdx((i) => i + 1); setTestResult(null); }}
                      className="w-full py-2.5 rounded-full text-sm font-semibold"
                      style={{ background: COLORS.teal, color: "#FFF" }}>
                      Следующее задание →
                    </button>
                  </div>
                )}
              </div>
            </div>
          );
        })()}

        {/* ---------- ПРОБНЫЙ ВАРИАНТ ЕГЭ (только русский язык) ---------- */}
        {tab === "exam" && track === "russian" && (() => {
          const EXAM_TITLES = {
            1: "Логико-смысловая связь", 2: "Значение слова", 3: "Характеристика текста",
            4: "Ударение", 5: "Паронимы", 6: "Лексическая сочетаемость",
            7: "Морфологические нормы", 8: "Грамматические ошибки", 9: "Корни",
            10: "Приставки, Ъ/Ь", 11: "Суффиксы", 12: "Личные окончания глаголов",
            13: "НЕ/НИ", 14: "Слитно/дефис/раздельно", 15: "Н/НН",
            16: "Однородные члены", 17: "Обособление", 18: "Вводные конструкции",
            19: "СПП", 20: "Разные виды связи", 21: "Пунктуационный анализ",
            22: "Тропы", 23: "Анализ содержания", 24: "Средства связи",
            25: "Лексический анализ", 26: "Средства связи", 27: "Сочинение",
          };
          const poolForTask = TESTS.filter((t) => t.examTask === examTaskNum);
          const cur = poolForTask.length ? poolForTask[0] : null;
          const doneCount = Object.keys(examProgress).length;

          if (examTaskNum === 27) {
            return (
              <div>
                <div className="rounded-xl p-4 mb-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                  <p className="text-sm" style={{ color: COLORS.ink }}>
                    Задание 27 — развёрнутое сочинение, у него нет краткого ответа для автопроверки.
                  </p>
                  <button onClick={() => setTab("essay")} className="mt-3 px-4 py-2 rounded-full text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF" }}>
                    Перейти к тренажёру сочинений →
                  </button>
                </div>
              </div>
            );
          }

          return (
            <div>
              <div className="rounded-xl p-4 mb-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <p className="text-xs mb-3" style={{ color: COLORS.inkSoft }}>
                  27 позиций подряд, как настоящий бланк. Пройдено: {doneCount} из 26 (не считая сочинения).
                </p>
                <div className="flex flex-wrap gap-1">
                  {Array.from({ length: 26 }, (_, i) => i + 1).map((n) => {
                    const done = examProgress[n];
                    const active = n === examTaskNum;
                    return (
                      <button key={n} onClick={() => { setExamTaskNum(n); setExamResult(null); }}
                        className="flex items-center justify-center rounded text-xs font-semibold"
                        style={{ width: 28, height: 28,
                                 background: active ? COLORS.onyx : done ? (done.ok ? COLORS.sageSoft : COLORS.rustSoft) : COLORS.paperDeep,
                                 color: active ? COLORS.onyxText : done ? (done.ok ? COLORS.sage : COLORS.rust) : COLORS.inkSoft }}>
                        {n}
                      </button>
                    );
                  })}
                  <button onClick={() => { setExamTaskNum(27); setExamResult(null); }}
                    className="flex items-center justify-center rounded text-xs font-semibold px-2"
                    style={{ height: 28, background: examTaskNum === 27 ? COLORS.onyx : COLORS.tealSoft, color: examTaskNum === 27 ? COLORS.onyxText : COLORS.teal }}>
                    27 · соч.
                  </button>
                </div>
              </div>

              {!cur ? (
                <div className="rounded-2xl p-10 text-center" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                  <p style={{ color: COLORS.inkSoft }}>Для этого номера пока нет задания в банке.</p>
                </div>
              ) : (
                <div className="rounded-2xl p-6" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                  <div className="flex gap-2 flex-wrap mb-3 items-center">
                    <Pill tone="teal">Задание {examTaskNum}</Pill>
                    <span className="text-sm font-semibold" style={{ color: COLORS.ink }}>{EXAM_TITLES[examTaskNum]}</span>
                    <Pill tone="blue">{cur.type === "multi" ? "выбор нескольких" : "краткий ответ"}</Pill>
                  </div>
                  <p className="text-sm leading-relaxed mb-3" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink, whiteSpace: "pre-line" }}>{cur.q}</p>
                  {cur.opts.length > 0 && (
                    <ol className="mb-4 space-y-1.5" style={{ listStyle: "none", padding: 0 }}>
                      {cur.opts.map((o, i) => (
                        <li key={i} className="text-sm flex gap-2" style={{ color: COLORS.inkSoft }}>
                          <span className="flex-shrink-0 font-semibold" style={{ color: COLORS.blue, fontFamily: "'IBM Plex Mono', monospace" }}>{i + 1})</span>
                          <span>{o}</span>
                        </li>
                      ))}
                    </ol>
                  )}
                  {!examResult ? (
                    <div className="flex gap-2">
                      <input key={cur.id} ref={examInputRef} defaultValue="" placeholder="ответ"
                        onKeyDown={(e) => { if (e.key === "Enter") {
                          const raw = examInputRef.current ? examInputRef.current.value : "";
                          const ok = normalizeAnswer(raw, cur.type) === normalizeAnswer(cur.a, cur.type) && raw.trim().length > 0;
                          setExamResult({ ok, given: raw.trim() });
                          setExamProgress((p) => ({ ...p, [examTaskNum]: { ok } }));
                        } }}
                        className="flex-1 px-3 py-2.5 rounded-2xl text-sm"
                        style={{ background: COLORS.paperDeep, border: `1px solid ${COLORS.line}`, color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }} />
                      <button onClick={() => {
                        const raw = examInputRef.current ? examInputRef.current.value : "";
                        const ok = normalizeAnswer(raw, cur.type) === normalizeAnswer(cur.a, cur.type) && raw.trim().length > 0;
                        setExamResult({ ok, given: raw.trim() });
                        setExamProgress((p) => ({ ...p, [examTaskNum]: { ok } }));
                      }} className="px-5 py-2.5 rounded-full text-sm font-semibold" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>Проверить</button>
                    </div>
                  ) : (
                    <div>
                      <div className="rounded-2xl p-4 mb-3" style={{ background: examResult.ok ? COLORS.sageSoft : COLORS.rustSoft }}>
                        <p className="text-sm font-semibold mb-1" style={{ color: examResult.ok ? COLORS.sage : COLORS.rust }}>
                          {examResult.ok ? "✓ Верно" : `✕ Неверно. Твой ответ: ${examResult.given || "—"} · Правильный: ${cur.a}`}
                        </p>
                        <p className="text-sm leading-relaxed mt-2" style={{ color: COLORS.ink }}>{cur.why}</p>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => setExamTaskNum((n) => Math.max(1, n - 1))} disabled={examTaskNum === 1}
                          className="flex-1 py-2.5 rounded-full text-sm font-semibold" style={{ background: COLORS.paperDeep, color: COLORS.ink, opacity: examTaskNum === 1 ? 0.4 : 1 }}>← Назад</button>
                        <button onClick={() => { setExamTaskNum((n) => Math.min(27, n + 1)); setExamResult(null); }}
                          className="flex-1 py-2.5 rounded-full text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF" }}>Далее →</button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })()}

        {/* ---------- СОЧИНЕНИЕ (только русский язык) ---------- */}
        {tab === "essay" && track === "russian" && (() => {
          const PROMPTS = [
            { title: "Проблема выбора между личным успехом и верностью принципам",
              hint: "Подходит для аргументации: конфликт индивидуальной выгоды и морального долга." },
            { title: "Роль наставника в становлении личности",
              hint: "Подходит для аргументации: влияние учителя, старшего товарища на формирование ценностей." },
            { title: "Может ли технический прогресс разрушать человеческие связи?",
              hint: "Подходит для аргументации: противопоставление удобства и утраты живого общения." },
            { title: "Что важнее — талант или упорный труд?",
              hint: "Подходит для аргументации: примеры людей, добившихся успеха вопреки отсутствию явного таланта." },
            { title: "Цена предательства: можно ли простить того, кто предал?",
              hint: "Подходит для аргументации: моральная дилемма прощения и последствий доверия." },
          ];
          const CRITERIA = [
            "Сформулирована ли проблема как чёткий вопрос (а не общая тема)?",
            "Приведены ли ДВА конкретных примера из текста для комментария?",
            "Объяснена ли СВЯЗЬ между двумя примерами (противопоставление/причина-следствие/дополнение)?",
            "Отдельно сформулирована позиция автора (не пересказ, а вывод)?",
            "Высказано собственное мнение с обоснованием (согласие или несогласие)?",
            "Есть краткий вывод в конце?",
            "Объём от 150 слов?",
            "Нет фактических искажений содержания текста?",
          ];
          const prompt = PROMPTS[essayPromptIdx % PROMPTS.length];
          const checkedCount = Object.values(essayChecklist).filter(Boolean).length;

          return (
            <div className="space-y-4">
              <div className="rounded-xl p-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <p className="text-sm" style={{ color: COLORS.ink }}>
                  Здесь нет автопроверки текста — сочинение оценивается по критериям, а не по ключу.
                  Пиши на бумаге или в заметках, затем прогоняй через чек-лист ниже.
                </p>
              </div>

              <div className="rounded-2xl p-6" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <div className="flex items-center justify-between mb-3">
                  <Pill tone="teal">Тема для практики {(essayPromptIdx % PROMPTS.length) + 1} / {PROMPTS.length}</Pill>
                  <button onClick={() => { setEssayPromptIdx((i) => i + 1); setEssayChecklist({}); }}
                    className="text-xs font-semibold px-3 py-1.5 rounded-full" style={{ background: COLORS.paperDeep, color: COLORS.ink }}>
                    Следующая тема →
                  </button>
                </div>
                <p className="text-base font-semibold mb-2" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>{prompt.title}</p>
                <p className="text-sm" style={{ color: COLORS.inkSoft }}>{prompt.hint}</p>
              </div>

              <div className="rounded-2xl p-6" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <p className="text-sm font-semibold mb-1" style={{ fontFamily: "'Figtree', sans-serif" }}>Чек-лист самопроверки</p>
                <p className="text-xs mb-4" style={{ color: COLORS.inkSoft }}>{checkedCount} из {CRITERIA.length} пунктов отмечено</p>
                <div className="space-y-2">
                  {CRITERIA.map((c, i) => (
                    <button key={i} onClick={() => setEssayChecklist((p) => ({ ...p, [i]: !p[i] }))}
                      className="w-full text-left flex items-center gap-2.5 py-1.5">
                      <span className="flex items-center justify-center rounded flex-shrink-0"
                        style={{ width: 18, height: 18, border: `1.5px solid ${essayChecklist[i] ? COLORS.teal : COLORS.line}`, background: essayChecklist[i] ? COLORS.teal : "transparent" }}>
                        {essayChecklist[i] && <Check size={12} color="#FFF" />}
                      </span>
                      <span className="text-sm" style={{ color: COLORS.ink }}>{c}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="rounded-2xl p-4" style={{ background: COLORS.blueSoft }}>
                <p className="text-xs" style={{ color: COLORS.ink }}>
                  Полная структура и разбор блока «комментарий» — в теме «Задание 27» на карте тем.
                  Для итогового сочинения (допуск к ЕГЭ) — отдельная тема «Итоговое сочинение» с требованиями и разделами тем.
                </p>
              </div>
            </div>
          );
        })()}

        {/* ---------- ТЕСТЫ (русский язык): сетка по номерам заданий + детальный экран ---------- */}
        {tab === "tests" && track === "russian" && (() => {
          const EXAM_TITLES = {
            1: "Логико-смысловая связь", 2: "Значение слова", 3: "Характеристика текста",
            4: "Ударение", 5: "Паронимы", 6: "Лексическая сочетаемость",
            7: "Морфологические нормы", 8: "Грамматические ошибки", 9: "Корни",
            10: "Приставки, Ъ/Ь", 11: "Суффиксы", 12: "Личные окончания глаголов",
            13: "НЕ/НИ", 14: "Слитно/дефис/раздельно", 15: "Н/НН",
            16: "Однородные члены", 17: "Обособление", 18: "Вводные конструкции",
            19: "СПП", 20: "Разные виды связи", 21: "Пунктуационный анализ",
            22: "Тропы", 23: "Анализ содержания", 24: "Средства связи",
            25: "Лексический анализ", 26: "Средства связи", 27: "Сочинение",
          };
          const getPool = (num) => (num === 1 ? TASK1_BANK : TESTS.filter((t) => t.examTask === num));
          const statFor = (num) => taskStatsAll[num] || { right: 0, total: 0 };
          const pctFor = (num) => { const s = statFor(num); return s.total ? Math.round((s.right / s.total) * 100) : 0; };

          if (taskGridNum === null) {
            return (
              <div>
                <div className="rounded-xl p-4 mb-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                  <p className="text-xs" style={{ color: COLORS.inkSoft }}>
                    27 заданий части 1, каждое — отдельный модуль. Выбери номер и решай в формате,
                    приближённом к реальному экзамену.
                  </p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                  {Array.from({ length: 27 }, (_, i) => i + 1).map((num) => {
                    const pool = getPool(num);
                    const pct = pctFor(num);
                    const st = statFor(num);
                    const disabled = num !== 27 && pool.length === 0;
                    return (
                      <button key={num} disabled={disabled}
                        onClick={() => { setTaskGridNum(num); setTaskIdx(0); setTaskResult(null); setTaskWordType(null); }}
                        className="relative text-left rounded-2xl overflow-hidden"
                        style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, opacity: disabled ? 0.45 : 1, cursor: disabled ? "default" : "pointer" }}>
                        <div className="absolute inset-0" style={{ width: `${pct}%`, background: pct > 0 ? (toneForValue(pct) + "18") : "transparent", transition: "width .3s ease" }} />
                        <div className="relative p-3.5 flex items-center gap-3">
                          <span className="flex items-center justify-center flex-shrink-0 rounded-2xl font-bold"
                            style={{ width: 34, height: 34, background: COLORS.onyx, color: COLORS.onyxText, fontFamily: "'IBM Plex Mono', monospace", fontSize: "0.95rem" }}>
                            {num}
                          </span>
                          <div className="min-w-0 flex-1">
                            <p className="text-sm font-semibold truncate" style={{ color: COLORS.ink, fontFamily: "'Figtree', sans-serif" }}>{EXAM_TITLES[num]}</p>
                            <p className="text-xs mt-0.5" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                              {num === 27 ? "сочинение — во вкладке «Сочинение»" : disabled ? "нет заданий" : `${pool.length} заданий · ${st.total ? `решено ${st.total}, точность ${pct}%` : "не начато"}`}
                            </p>
                          </div>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          }

          const num = taskGridNum;
          const fullPool = getPool(num);
          const wordTypes = num === 1 ? [...new Set(fullPool.map((t) => t.wordType).filter(Boolean))].sort() : [];
          const pool = taskWordType ? fullPool.filter((t) => t.wordType === taskWordType) : fullPool;
          const cur = pool.length ? pool[taskIdx % pool.length] : null;

          function checkTaskGrid() {
            if (!cur) return;
            const raw = taskInputRef.current ? taskInputRef.current.value : "";
            const norm = raw.trim().toLowerCase().replace(/ё/g, "е").replace(/[.,!?;]/g, "");
            const variants = (cur.altAnswers || [cur.a]).map((a) => normalizeAnswer(a, cur.type).replace(/ё/g, "е"));
            const given = normalizeAnswer(raw, cur.type).replace(/ё/g, "е");
            const ok = (variants.includes(norm) || variants.includes(given)) && raw.trim().length > 0;
            setTaskResult({ ok, given: raw.trim() });
            setTaskStatsAll((prev) => {
              const p = prev[num] || { right: 0, total: 0 };
              const next = { ...prev, [num]: { right: p.right + (ok ? 1 : 0), total: p.total + 1 } };
              try { window.storage.set("ru-taskstats", JSON.stringify(next), false); } catch (e) { /* не критично */ }
              return next;
            });
          }

          return (
            <div>
              <button onClick={() => setTaskGridNum(null)} className="flex items-center gap-1.5 text-sm mb-4" style={{ color: COLORS.inkSoft }}>
                <ArrowLeft size={15} /> Ко всем заданиям
              </button>

              <div className="rounded-xl p-4 mb-4 flex items-center gap-3 flex-wrap" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <Pill tone="teal">Задание {num}</Pill>
                <span className="text-sm font-semibold" style={{ color: COLORS.ink, fontFamily: "'Figtree', sans-serif" }}>{EXAM_TITLES[num]}</span>
                {statFor(num).total > 0 && (
                  <span className="text-xs ml-auto" style={{ color: toneForValue(pctFor(num)), fontFamily: "'IBM Plex Mono', monospace" }}>
                    точность {pctFor(num)}% ({statFor(num).right}/{statFor(num).total})
                  </span>
                )}
              </div>

              {wordTypes.length > 0 && (
                <div className="flex gap-1.5 flex-wrap mb-4">
                  <button onClick={() => { setTaskWordType(null); setTaskIdx(0); setTaskResult(null); }}
                    className="text-xs font-medium px-2.5 py-1.5 rounded-2xl"
                    style={{ background: !taskWordType ? COLORS.teal : COLORS.paperDeep, color: !taskWordType ? "#FFF" : COLORS.inkSoft }}>
                    Все ({fullPool.length})
                  </button>
                  {wordTypes.map((wt) => (
                    <button key={wt} onClick={() => { setTaskWordType(taskWordType === wt ? null : wt); setTaskIdx(0); setTaskResult(null); }}
                      className="text-xs font-medium px-2.5 py-1.5 rounded-2xl"
                      style={{ background: taskWordType === wt ? COLORS.teal : COLORS.paperDeep, color: taskWordType === wt ? "#FFF" : COLORS.inkSoft }}>
                      {wt} · {fullPool.filter((t) => t.wordType === wt).length}
                    </button>
                  ))}
                </div>
              )}

              {!cur ? (
                <div className="rounded-2xl p-10 text-center" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                  <p style={{ color: COLORS.inkSoft }}>Заданий по этому номеру пока нет.</p>
                </div>
              ) : (
                <div>
                  <div className="text-xs mb-2" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                    {(taskIdx % pool.length) + 1} / {pool.length}
                  </div>
                  <div className="rounded-2xl overflow-hidden" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                    {cur.frag && (
                      <div className="p-6" style={{ background: COLORS.paperDeep, borderBottom: `1px solid ${COLORS.line}` }}>
                        <p className="text-xs uppercase tracking-wide mb-2.5" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>Текст задания</p>
                        <p style={{ color: COLORS.ink, fontFamily: "'Figtree', sans-serif", fontSize: "1.0625rem", lineHeight: 1.8 }}>{cur.frag}</p>
                      </div>
                    )}
                    <div className="p-6">
                      <p style={{ color: COLORS.ink, fontFamily: "'Figtree', ui-sans-serif, sans-serif", fontSize: "1rem", lineHeight: 1.75, fontWeight: 450 }}>{cur.q}</p>
                      {(cur.opts || []).length > 0 && (
                        <ol className="mt-4 space-y-2" style={{ listStyle: "none", padding: 0 }}>
                          {cur.opts.map((o, i) => (
                            <li key={i} className="flex gap-2.5" style={{ color: COLORS.ink, fontSize: "1rem", lineHeight: 1.6 }}>
                              <span className="flex-shrink-0 font-semibold" style={{ color: COLORS.blue, fontFamily: "'IBM Plex Mono', monospace" }}>{i + 1})</span>
                              <span>{o}</span>
                            </li>
                          ))}
                        </ol>
                      )}
                      <div className="mt-5">
                        {!taskResult ? (
                          <div className="flex gap-2">
                            <input key={cur.id} ref={taskInputRef} defaultValue="" placeholder="ответ"
                              onKeyDown={(e) => { if (e.key === "Enter") checkTaskGrid(); }}
                              className="flex-1 px-3 py-2.5 rounded-2xl text-sm"
                              style={{ background: COLORS.paperDeep, border: `1px solid ${COLORS.line}`, color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }} />
                            <button onClick={checkTaskGrid} className="px-5 py-2.5 rounded-full text-sm font-semibold" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>Проверить</button>
                          </div>
                        ) : (
                          <div>
                            <div className="rounded-2xl p-4 mb-3" style={{ background: taskResult.ok ? COLORS.sageSoft : COLORS.rustSoft }}>
                              <p className="text-sm font-semibold mb-1" style={{ color: taskResult.ok ? COLORS.sage : COLORS.rust }}>
                                {taskResult.ok ? "✓ Верно" : `✕ Неверно. Твой ответ: ${taskResult.given || "—"} · Правильный: ${cur.a}`}
                              </p>
                              <p className="text-sm leading-relaxed mt-2" style={{ color: COLORS.ink }}>{cur.why}</p>
                            </div>
                            <button onClick={() => { setTaskIdx((i) => i + 1); setTaskResult(null); }}
                              className="w-full py-2.5 rounded-full text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF" }}>
                              Следующее задание →
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          );
        })()}


        {/* ---------- БУСТЕРЫ ---------- */}
        {tab === "boosters" && (
          <div className="space-y-5">
            <div className="rounded-xl p-4 text-xs" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, color: COLORS.inkSoft }}>
              Сюда автоматически попадают тесты и карточки, на которые ты ответил неверно — в экзамене 1 тура, в практике по теме или в обычных тестах. Список обновляется после каждого ответа.
            </div>

            {/* ---------- Блок 1 (верхний): тесты с ошибками — можно пересдать прямо здесь ---------- */}
            <div className="rounded-2xl p-5" style={{ background: COLORS.surface, border: `1px solid ${COLORS.rust}33` }}>
              <div className="flex items-center gap-2 mb-3">
                <ListChecks size={16} color={COLORS.rust} />
                <p className="text-sm font-semibold" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>Тесты, где ошибся</p>
                <span className="text-xs ml-auto" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{hardTestsRaw.length}</span>
              </div>
              {hardTestsRaw.length === 0 ? (
                <p className="text-xs text-center py-6" style={{ color: COLORS.inkSoft }}>Ошибок в тестах нет — чисто!</p>
              ) : (
                <div className="space-y-3">
                  {hardTestsRaw.map((t) => {
                    const sel = boosterSelected[t.id] || [];
                    const revealed = boosterRevealed[t.id];
                    const isSingle = t.a.length === 1;
                    return (
                      <div key={t.id} className="rounded-xl p-4" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.rust}44` }}>
                        <Pill tone="rust">{allTopicsRef.current.find((x) => x.key === t.topic)?.label || t.topic}</Pill>
                        <p className="text-sm mt-2 mb-2" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>{t.q}</p>
                        {!revealed ? (
                          <>
                            <div className="space-y-1.5 mb-2">
                              {t.opts.map((o, i) => {
                                const num = i + 1;
                                const on = sel.includes(num);
                                return (
                                  <button key={i}
                                    onClick={() => {
                                      if (isSingle) {
                                        setBoosterSelected((p) => ({ ...p, [t.id]: [num] }));
                                        setTimeout(() => submitBoosterAnswer(t), 60);
                                      } else {
                                        setBoosterSelected((p) => ({ ...p, [t.id]: on ? sel.filter((x) => x !== num) : [...sel, num] }));
                                      }
                                    }}
                                    className="w-full text-left px-3 py-2 rounded-lg text-xs flex gap-2"
                                    style={{ background: on ? COLORS.tealSoft : COLORS.paperDeep, border: `1.5px solid ${on ? COLORS.teal : "transparent"}`, color: COLORS.ink }}>
                                    <span className="font-semibold flex-shrink-0" style={{ color: COLORS.blue, fontFamily: "'IBM Plex Mono', monospace" }}>{num})</span>
                                    <span>{o}</span>
                                  </button>
                                );
                              })}
                            </div>
                            {!isSingle && (
                              <button onClick={() => submitBoosterAnswer(t)} disabled={sel.length === 0}
                                className="w-full py-2 rounded-lg text-xs font-semibold" style={{ background: COLORS.teal, color: "#FFF", opacity: sel.length === 0 ? 0.5 : 1 }}>
                                Ответить
                              </button>
                            )}
                          </>
                        ) : (
                          <div>
                            <div className="rounded-lg p-3 mb-2" style={{ background: revealed.ok ? COLORS.sageSoft : COLORS.rustSoft }}>
                              <p className="text-xs font-semibold mb-1" style={{ color: revealed.ok ? COLORS.sage : COLORS.rust }}>
                                {revealed.ok ? "✓ Верно — убрано из списка" : `✕ Твой ответ: ${revealed.given || "—"} · Правильный: ${t.a}`}
                              </p>
                              <p className="text-xs" style={{ color: COLORS.inkSoft }}>{t.why}</p>
                            </div>
                            {!revealed.ok && (
                              <button onClick={() => { setBoosterRevealed((p) => { const n = { ...p }; delete n[t.id]; return n; }); setBoosterSelected((p) => ({ ...p, [t.id]: [] })); }}
                                className="text-xs font-semibold px-3 py-1.5 rounded-full" style={{ background: COLORS.paperDeep, color: COLORS.inkSoft }}>
                                Попробовать ещё раз
                              </button>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* ---------- Блок 2 (нижний): карточки, отмеченные «не знал» ---------- */}
            <div className="rounded-2xl p-5" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}` }}>
              <div className="flex items-center gap-2 mb-3">
                <Brain size={16} color={COLORS.teal} />
                <p className="text-sm font-semibold" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>Карточки, которые не знал</p>
                <span className="text-xs ml-auto" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{hardCardsOnly.length}</span>
              </div>
              {hardCardsOnly.length === 0 ? (
                <div className="text-center py-6">
                  <Check size={24} color={COLORS.sage} className="mx-auto mb-2" />
                  <p className="text-xs" style={{ color: COLORS.inkSoft }}>Сложных карточек нет.</p>
                </div>
              ) : (
                <div className="space-y-2">
                  {hardCardsOnly.map((c) => (
                    <div key={c.id} className="rounded-xl p-4" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}` }}>
                      <p className="text-sm mb-2" style={{ fontFamily: "'Figtree', sans-serif", color: COLORS.ink }}>{c.front}</p>
                      <p className="text-sm" style={{ color: COLORS.inkSoft }}>{c.back}</p>
                      <button onClick={() => setStruggling((p) => { const n = { ...p }; delete n[c.id]; persist("struggling", n); return n; })}
                        className="text-xs font-semibold px-3 py-1.5 rounded-full mt-3" style={{ background: COLORS.sage, color: "#FFF" }}>
                        Усвоил, убрать
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* ---------- ПРОГРЕСС ---------- */}
        {tab === "progress" && (
          <div className="rounded-2xl p-6" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
            <h2 className="text-lg mb-3" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700 }}>Прогресс по разделу</h2>
            <div className="w-full h-3 rounded-full mb-2" style={{ background: COLORS.paperDeep }}>
              <div className="h-3 rounded-full" style={{ width: `${Math.min(progress, 100)}%`, background: toneForValue(Math.min(progress, 100)) }} />
            </div>
            <p className="text-sm mb-4" style={{ color: COLORS.inkSoft }}>
              Изучено {coreDone} из {core.length} обязательных тем{bonusDone > 0 ? `, плюс ${bonusDone} дополнительных` : ""}.
            </p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {[["Прогресс", progress + "%", toneForValue(progress)],
                ["Карточек в банке", String(CARDS.length), COLORS.teal],
                ["Сложных карточек", String(hardCards.length), hardCards.length ? COLORS.rust : COLORS.sage]].map(([k, v, c]) => (
                <div key={k} className="rounded-2xl p-3" style={{ background: COLORS.paperDeep }}>
                  <div className="text-xl font-bold" style={{ color: c, fontFamily: "'IBM Plex Mono', monospace" }}>{v}</div>
                  <div className="text-xs mt-0.5" style={{ color: COLORS.inkSoft }}>{k}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ---------- МАТЕРИАЛЫ ---------- */}
        {tab === "materials" && (
          <div className="space-y-4">
            {(track === "finlit" ? FINLIT_SOURCES : BIZ_SOURCES).map((d, i) => (
              <div key={i} className="rounded-2xl p-5" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
                <p className="font-semibold text-sm" style={{ fontFamily: "'Figtree', sans-serif" }}>{d.title}</p>
                <p className="text-xs mt-1 mb-3" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{d.source}</p>
                <pre className="text-xs whitespace-pre-wrap leading-relaxed p-3 rounded-2xl" style={{ background: COLORS.paperDeep, color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace", maxHeight: 400, overflowY: "auto" }}>{d.text}</pre>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}

function PrepPlan30Screen({ onBack, theme, onToggleTheme }) {
  const [openWeek, setOpenWeek] = useState(1);

  const Table = ({ cols, rows }) => (
    <div className="overflow-x-auto rounded-2xl mb-4" style={{ border: `1px solid ${COLORS.line}` }}>
      <table className="w-full text-sm" style={{ borderCollapse: "collapse" }}>
        <thead>
          <tr style={{ background: COLORS.paperDeep }}>
            {cols.map((c, i) => (
              <th key={i} className="text-left px-3 py-2 font-semibold" style={{ color: COLORS.ink, borderBottom: `1px solid ${COLORS.line}` }}>{c}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={i} style={{ borderTop: i > 0 ? `1px solid ${COLORS.line}` : "none" }}>
              {r.map((c, j) => (
                <td key={j} className="px-3 py-2 align-top" style={{ color: COLORS.inkSoft }}>{c}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  const H2 = ({ children }) => (
    <h2 className="text-xl mt-8 mb-3" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700, color: COLORS.ink }}>{children}</h2>
  );
  const H3 = ({ children }) => (
    <h3 className="text-base mt-5 mb-2 font-semibold" style={{ color: COLORS.ink }}>{children}</h3>
  );
  const P = ({ children }) => (
    <p className="text-sm leading-relaxed mb-3" style={{ color: COLORS.inkSoft }}>{children}</p>
  );

  const DayCard = ({ day, title, text }) => (
    <div className="rounded-xl p-4 mb-2.5" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
      <div className="flex items-baseline gap-2 mb-1">
        <span className="text-xs font-bold px-2 py-0.5 rounded-full" style={{ background: COLORS.onyx, color: COLORS.onyxText, fontFamily: "'IBM Plex Mono', monospace" }}>{day}</span>
        <p className="text-sm font-semibold" style={{ color: COLORS.ink }}>{title}</p>
      </div>
      <p className="text-sm leading-relaxed" style={{ color: COLORS.inkSoft }}>{text}</p>
    </div>
  );

  const weeks = [
    {
      n: 1, title: "Теоретическая база", range: "дни 1–7",
      days: [
        ["День 1", "Экономика: рынок и равновесие", "Спрос/предложение, равновесие, излишки потребителя/производителя — раздел «Экономика», карта тем."],
        ["День 2", "Бизнес: причинный вывод и издержки", "Причинный вывод и A/B-эксперименты, приростные издержки, ограниченный ресурс — новые, но вероятные темы."],
        ["День 3", "Финграм: права потребителя и термины", "Срок годности/службы/реализации/гарантийный — точное разграничение, налоговые вычеты."],
        ["День 4", "Экономика: эластичность", "Эластичность спроса — по цене, доходу, перекрёстная. Тема максимального приоритета."],
        ["День 5", "Бизнес: точка безубыточности и NPV", "Unit-экономика, точка безубыточности, оценка проектов. Прогнать практикумы."],
        ["День 6", "Финграм: страхование и риск", "Франшиза и система первого риска, диверсификация и риск, самозапрет на кредиты."],
        ["День 7", "Повторение + первая проверка", "По 10–15 карточек из каждого профиля в режиме «Не пройдено», честно отметить правильно/неправильно."],
      ],
    },
    {
      n: 2, title: "Расчётные задачи", range: "дни 8–14",
      days: [
        ["День 8", "Экономика: монополия и госвмешательство", "Монополия + налог/субсидия/квота на её выбор — максимальный приоритет в 2025/26."],
        ["День 9", "Бизнес: финансовая математика", "NPV/PV с неизвестной ставкой, ожидаемая доходность и риск."],
        ["День 10", "Финграм: расчётные задачи", "Франшиза, недвижимость vs вклад, венчур — расчётный практикум."],
        ["День 11", "Экономика: издержки фирмы", "Постоянные/переменные/предельные/средние издержки, точка пересечения MC и AC."],
        ["День 12", "Бизнес: макро для бизнеса", "Ключевая ставка, инфляция, курс валюты — эффект на конкретную компанию."],
        ["День 13", "Финграм: кредиты и депозиты", "Простые/сложные проценты, аннуитет vs дифференцированная схема."],
        ["День 14", "Контрольный день", "По 10 расчётных задач из каждого профиля без теории — зафиксировать конкретные ошибки."],
      ],
    },
    {
      n: 3, title: "Формат отборочного этапа", range: "дни 15–21",
      days: [
        ["День 15", "Экономика: международная торговля", "КПВ, сравнительное преимущество, автаркия, тариф — плюс тестовый прогон в формате «выберите все верные»."],
        ["День 16", "Бизнес: причинный вывод (углублённо)", "Повторно тесты по A/B-экспериментам — новая тема, нужна уверенность."],
        ["День 17", "Финграм: СБП и цифровые сервисы", "Система быстрых платежей, безопасность, банкротство физлица."],
        ["День 18", "Экономика: смешанный тест", "15–20 вопросов из банка вперемешку по темам недель 1–2."],
        ["День 19", "Бизнес: смешанный тест", "Аналогично, из тестового банка приложения."],
        ["День 20", "Финграм: смешанный тест", "Аналогично."],
        ["День 21", "День отдыха с лёгким повторением", "Пересмотреть карточки, отмеченные «неправильно» на этой неделе (раздел «Бустеры»)."],
      ],
    },
    {
      n: 4, title: "Слабые места и новые темы", range: "дни 22–28",
      days: [
        ["День 22", "Экономика: теория игр (новая тема)", "Появилась впервые в 2025/26 — логика доминирующих стратегий на простом примере."],
        ["День 23", "Бизнес: право и правовые риски", "Организационно-правовые формы, налоговые режимы 2026, ценовая дискриминация, патенты."],
        ["День 24", "Финграм: точные формулировки терминов", "Целый день — только термины, звучащие похоже, но означающие разное."],
        ["День 25", "Экономика: валютный рынок", "Факторы спроса на валюту — новая акцентная тема 2025/26."],
        ["День 26", "Разбор личной статистики", "Открыть прогресс по каждому профилю, найти темы с наименьшим % правильных ответов."],
        ["День 27", "Второй разбор статистики", "То же самое, для тем с ошибками на прошлой неделе (день 21)."],
        ["День 28", "Свободный день", "Ничего нового — спокойное повторение понятного, для уверенности."],
      ],
    },
    {
      n: 5, title: "Генеральная репетиция", range: "дни 29–30",
      days: [
        ["День 29", "Полный пробный вариант: экономика + бизнес", "Режим «Пробный вариант» подряд, с ограничением по времени. Объяснения смотреть только после завершения."],
        ["День 30", "Полный пробный вариант: финграм + разбор", "Финграм в том же режиме, затем разбор всех трёх вариантов — какие типы ошибок повторяются чаще."],
      ],
    },
  ];

  return (
    <div className="min-h-screen w-full" style={{ background: pageBackground(), backgroundSize: PAGE_BG_SIZE, color: COLORS.ink, fontFamily: "'Figtree', ui-sans-serif, sans-serif" }}>
      <header className="max-w-3xl mx-auto px-6 pt-10 pb-6">
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div>
            <button onClick={onBack} className="text-xs mb-2 flex items-center gap-1" style={{ color: COLORS.inkSoft }}>
              <ArrowLeft size={13} /> На главный экран
            </button>
            <p className="text-xs tracking-widest uppercase" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>Экономика · Основы бизнеса · Финграмотность</p>
            <h1 className="text-3xl sm:text-4xl mt-1" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700 }}>План подготовки — 30 дней</h1>
          </div>
          <div className="flex items-center gap-2">
            <SessionTimer />
            <button onClick={onToggleTheme} className="flex items-center gap-2 px-4 py-2.5 rounded-full" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
              {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-3xl mx-auto px-6 pb-20">
        <div className="rounded-2xl p-4 mb-6" style={{ background: COLORS.blueSoft }}>
          <p className="text-sm leading-relaxed" style={{ color: COLORS.ink }}>
            Составлен на основе сравнения демовариантов отборочного этапа за несколько лет по каждому профилю
            (там, где на диске было больше одного года), методических рекомендаций и критериев оценивания.
            Прогнозы тем — это оценка вероятности по паттернам прошлых лет, а не гарантия.
          </p>
        </div>

        <H2>1. Экономика — сравнение по годам и прогноз</H2>
        <P>Сравнивались демоварианты 2023/2024 и 2025/2026 годов, 10 и 11 классы (4 документа).</P>
        <H3>Ключевое наблюдение: рост уровня абстракции</H3>
        <P>2023/2024 — задания в основном на качественное рассуждение: интерпретация новостных заголовков,
        эффект на макропоказатели «при прочих равных», плюсы/минусы ВВП, эффект налога на монополиста в общих терминах.</P>
        <P>2025/2026 — заметно больше формального аппарата: спрос задан явной функцией цены, нужно определить
        свойства оптимума через анализ формулы; задачи на теорию игр с числовыми таблицами выигрышей; работа
        с кривой торговых возможностей и точными координатами.</P>
        <TKey>Расчётные и формально-математические задачи — не резерв, а обязательная часть подготовки. Одной интуиции уже недостаточно.</TKey>

        <H3>Темы со стабильно высокой вероятностью</H3>
        <Table
          cols={["Тема", "Год(ы) обнаружения", "Приоритет"]}
          rows={[
            ["Эластичность спроса (по цене, доходу, перекрёстная)", "2023/24, 2025/26", "Максимальный"],
            ["Международная торговля, сравнительное преимущество, КПВ", "2023/24, 2025/26", "Максимальный"],
            ["ВВП и его недостатки как показателя", "2023/24", "Высокий"],
            ["Монополия: эффект налогов/субсидий/квот", "2023/24, 2025/26", "Максимальный"],
            ["Валютный рынок, факторы спроса на валюту", "2025/26", "Высокий"],
            ["Издержки фирмы (постоянные/переменные/предельные)", "2023/24", "Высокий"],
            ["Интерпретация новостных заголовков (макро)", "2023/24, 2025/26", "Высокий"],
            ["Рынок труда, занятость, структурные сдвиги", "2023/24", "Средний"],
          ]}
        />
        <H3>Новое / усложнившееся — особое внимание</H3>
        <P><b>Теория игр</b> в формате конкретных таблиц выигрышей (дуополия) — раньше почти не встречалось, в 2025/26 есть.</P>
        <P><b>Функциональный анализ спроса монополиста</b> — спрос задан формулой вида Q = A/Pⁿ, нужно понимать зависимость оптимальной цены от параметров.</P>
        <P><b>ОПЕК, нефтяной рынок</b> — специфичные факты о картелях в сырьевых рынках.</P>
        <H3>Прогноз вероятного состава варианта (11 класс)</H3>
        <TSteps title="Ожидаемая структура — 5-6 заданий по 5 баллов, множественный выбор со штрафом"
          steps={[
            { t: "Интерпретация макроэкономических новостей (заголовки)" },
            { t: "Эластичность спроса — с числовым или качественным сценарием" },
            { t: "Монополия + государственное вмешательство (налог/субсидия/квота/потолок цен)" },
            { t: "Международная торговля / КПВ / сравнительное преимущество" },
            { t: "Задача с формальным заданием спроса или издержек (расчётная)" },
            { t: "Теория игр ИЛИ валютный рынок ИЛИ рынок труда" },
          ]}
        />

        <H2>2. Основы бизнеса — сравнение и прогноз</H2>
        <P>Сравнивались демоверсия 1 тура 2026/2027 (прочитана полностью, 50 вопросов) и более старый вариант 2025 года.</P>
        <H3>Официальная структура — 14 тем программы</H3>
        <P>Рынок и конкуренция · Потребитель и продукт · Маркетинг и продажи · Предпринимательская идея · Ресурсы
        и эффективность · Операции и технологии · Организация и люди · Стратегия · Финансовый результат ·
        Финансирование и риск · Правовые основы · Госполитика и макро · Социальная среда · Международный бизнес.</P>
        <H3>Ключевое наблюдение</H3>
        <P>Демовариант 2026/2027 — это не только бизнес-теория, а прикладная экономика и статистика внутри
        бизнес-контекста: причинный вывод и эксперименты (A/B-тесты, смешивающие переменные), управленческий
        учёт (приростные издержки, вклад на дефицитный ресурс, невозвратные издержки), финансовая математика
        (NPV, ожидаемая доходность, реальная ставка), макроэкономика для бизнеса.</P>
        <Table
          cols={["Тема", "Уровень уверенности"]}
          rows={[
            ["Причинный вывод / A-B тест / смешивающая переменная", "Высокий"],
            ["Приростные издержки и решение о доп. заказе", "Высокий"],
            ["Точка безубыточности, вклад, маржинальность", "Высокий"],
            ["NPV / приведённая стоимость", "Высокий"],
            ["Ограниченный ресурс — выбор продукта", "Средне-высокий"],
            ["Финансовая отчётность (баланс, прибыль vs. денежный поток)", "Средне-высокий"],
            ["Организационно-правовые формы, налоговые режимы", "Средний"],
            ["Макро для бизнеса (ставка, инфляция, курс)", "Средний"],
            ["Sunk cost / издержки переключения", "Средний"],
          ]}
        />
        <TKey>Ожидай микс количественных задач (30–40% вопросов) и качественных вопросов на управленческую логику — с явным креном в строгое экономическое мышление, а не общие советы.</TKey>

        <H2>3. Финансовая грамотность — сравнение и прогноз</H2>
        <P>Сравнивались демо «старые задания 2025 года» и текущий демо 1 тура — содержательно близки, но состав не идентичен.</P>
        <H3>Ключевое наблюдение</H3>
        <P>Финграм в отличие от экономики и бизнеса опирается на актуальное законодательство РФ: базовые темы
        (страхование, вычеты, диверсификация, кредиты, подушка безопасности) стабильны из года в год, но
        появляются новые нормы — например, самозапрет на кредиты, актуальные лимиты самозанятости.</P>
        <Table
          cols={["Тема", "Уровень уверенности"]}
          rows={[
            ["Права потребителя: гарантийный/срок годности/службы/реализации (термины путают специально)", "Максимальный"],
            ["Виды и правила страхования (франшиза, первый риск, ОСАГО)", "Высокий"],
            ["Налоговые вычеты (социальный, имущественный)", "Высокий"],
            ["Диверсификация, риск, реальная/номинальная доходность", "Высокий"],
            ["Финансовая подушка безопасности", "Высокий"],
            ["Самозапрет на кредиты (новая тема)", "Высокий — новый закон"],
            ["СБП, дистанционные банковские услуги", "Средний"],
            ["Банкротство физлица, кто может инициировать", "Средний"],
          ]}
        />
        <TKey>Задания на точные определения терминов с похожим звучанием — фирменный стиль отборочного этапа по финграму. Учи не общий смысл, а точные формальные границы каждого термина.</TKey>

        <H2>4. Понедельный план</H2>
        <P>Все три профиля идут параллельно: по будням — один профиль в фокусе плюс лёгкое повторение двух других, выходные — сводные тесты и слабые места.</P>

        <div className="flex gap-1.5 flex-wrap mb-4">
          {weeks.map((w) => (
            <button key={w.n} onClick={() => setOpenWeek(w.n)}
              className="text-xs font-medium px-3 py-1.5 rounded-2xl"
              style={{ background: openWeek === w.n ? COLORS.onyx : COLORS.paperDeep, color: openWeek === w.n ? COLORS.onyxText : COLORS.inkSoft }}>
              Неделя {w.n} · {w.range}
            </button>
          ))}
        </div>

        {weeks.filter((w) => w.n === openWeek).map((w) => (
          <div key={w.n}>
            <p className="text-sm font-semibold mb-3" style={{ color: COLORS.ink }}>{w.title}</p>
            {w.days.map((d, i) => <DayCard key={i} day={d[0]} title={d[1]} text={d[2]} />)}
          </div>
        ))}

        <H2>5. Как проходить сам день отборочного этапа</H2>
        <TSteps title="Короткий чек-лист"
          steps={[
            { t: "Читай все пять вариантов ответа, даже если первый кажется явно верным — штрафуют и за лишние отметки." },
            { t: "При расчётных задачах выпиши формулу перед тем, как считать — не держи всё в уме." },
            { t: "Если не уверен — отметь меньше вариантов, чем гадать: штраф за ошибку часто дороже недобранного балла." },
            { t: "Экономика и Бизнес пересекаются по темам (издержки, монополия, NPV) — знакомая механика в непривычной формулировке это тот же принцип." },
            { t: "Не трать больше 3-4 минут на один вопрос — если завис, отметь то, в чём уверен, и возвращайся в конце." },
          ]}
        />

        <H2>6. Честно о пределах плана</H2>
        <P>Прогнозы тем — анализ вероятности по двум-трём годам данных, не гарантия. Материала для сравнения
        по экономике было больше (4 демоварианта), чем по бизнесу и финграму (по 2) — прогноз по экономике
        поэтому надёжнее.</P>
        <P>30 дней при параллельной подготовке по трём профилям — плотный, но реалистичный график при 1.5–2
        часах занятий в день. Если времени меньше — в первую очередь сохраняй недели 1 и 3 (база + формат),
        жертвуй неделей 4 (углублением).</P>
      </main>
    </div>
  );
}


