/* Глобальный поиск: компактная кнопка в шапке, результаты в модальном окне —
   так выпадающий список не перекрывает содержимое страницы. */

/* Умный поиск тем внутри раздела: ищет по названию, кратким заметкам (методы/ловушки/формулы)
   и по полному тексту урока. Показывает, где найдено совпадение. */
function TopicSearch({ allTopics, onGo }) {
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(false);
  const inputRef = React.useRef(null);

  useEffect(() => {
    if (open && inputRef.current) {
      const id = setTimeout(() => { try { inputRef.current.focus(); } catch (e) { /* не критично */ } }, 30);
      return () => clearTimeout(id);
    }
  }, [open]);

  useEffect(() => {
    const onKey = (e) => {
      const inField = e.target && ["INPUT", "TEXTAREA"].includes(e.target.tagName);
      if (e.key === "/" && !inField) { e.preventDefault(); setOpen(true); }
      else if (e.key === "Escape") { setOpen(false); setQ(""); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const socialTextByKey = useMemo(() => {
    const map = {};
    if (typeof SOCIAL_THEORY_ALL !== "undefined") {
      for (const t of SOCIAL_THEORY_ALL) map[t.key] = (map[t.key] || "") + " " + (t.paragraphs || []).join(" ");
    }
    if (typeof SOCIAL_LESSONS_ALL !== "undefined") {
      for (const t of SOCIAL_LESSONS_ALL) map[t.key] = (map[t.key] || "") + " " + (t.bullets || []).join(" ");
    }
    if (typeof SOCIAL_TOPIC_CHEATS !== "undefined") {
      for (const key of Object.keys(SOCIAL_TOPIC_CHEATS)) map[key] = (map[key] || "") + " " + SOCIAL_TOPIC_CHEATS[key].join(" ");
    }
    return map;
  }, []);

  const index = useMemo(() => allTopics.map((t) => {
    const fnName = DETAILED_THEORY_COMPONENTS[t.key] ? DETAILED_THEORY_COMPONENTS[t.key].name : null;
    const componentLessonText = fnName ? (LESSON_TEXT_INDEX[fnName] || "") : "";
    const socialText = socialTextByKey[t.key] || "";
    const lessonText = componentLessonText || socialText;
    const shortNotes = [...(t.methods || []), ...(t.traps || []), ...(t.formulas || [])].join(" ");
    return { key: t.key, label: t.label, shortNotes, lessonText, hasLesson: !!fnName || !!socialText };
  }), [allTopics, socialTextByKey]);

  const found = useMemo(() => {
    const needle = q.trim().toLowerCase();
    if (needle.length < 2) return [];
    const results = [];
    for (const item of index) {
      const inLabel = item.label.toLowerCase().includes(needle);
      const inNotes = item.shortNotes.toLowerCase().includes(needle);
      const inLesson = item.lessonText.toLowerCase().includes(needle);
      if (inLabel || inNotes || inLesson) {
        let where = inLabel ? "в названии" : inNotes ? "в кратких заметках" : "в тексте урока";
        let snippet = "";
        if (!inLabel) {
          const src = inNotes ? item.shortNotes : item.lessonText;
          const idx = src.toLowerCase().indexOf(needle);
          const start = Math.max(0, idx - 40);
          snippet = (start > 0 ? "…" : "") + src.slice(start, idx + needle.length + 60) + "…";
        }
        results.push({ ...item, where, snippet });
      }
      if (results.length >= 15) break;
    }
    return results;
  }, [q, index]);

  return (
    <>
      <button onClick={() => setOpen(true)}
        className="flex items-center gap-2 px-4 py-2.5 rounded-full text-sm"
        style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, color: COLORS.inkSoft }}>
        <Search size={15} />
        <span className="hidden sm:inline">Поиск по разделу</span>
        <span className="hidden sm:inline text-xs px-1.5 py-0.5 rounded" style={{ background: COLORS.paperDeep, fontFamily: "'IBM Plex Mono', monospace" }}>/</span>
      </button>
      {open && (
        <div className="fixed inset-0 z-50 flex items-start justify-center pt-24 px-4"
          style={{ background: "rgba(0,0,0,0.35)" }} onClick={() => { setOpen(false); setQ(""); }}>
          <div className="w-full max-w-xl overflow-hidden"
            style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, borderRadius: 24, boxShadow: "0 16px 48px rgba(0,0,0,0.25)" }}
            onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-2 px-4 py-3" style={{ borderBottom: `1px solid ${COLORS.line}` }}>
              <Search size={16} color={COLORS.inkSoft} />
              <input ref={inputRef} value={q} onChange={(e) => setQ(e.target.value)}
                placeholder="Ищи по названию, правилу или примеру из урока…"
                className="flex-1 bg-transparent text-sm outline-none" style={{ color: COLORS.ink }} />
              <button onClick={() => { setOpen(false); setQ(""); }} style={{ color: COLORS.inkSoft }}><X size={16} /></button>
            </div>
            <div style={{ maxHeight: 420, overflowY: "auto" }}>
              {q.trim().length < 2 ? (
                <p className="px-4 py-6 text-sm text-center" style={{ color: COLORS.inkSoft }}>
                  Введите минимум два символа. Поиск идёт по названиям тем, коротким заметкам
                  и полному тексту {Object.keys(LESSON_TEXT_INDEX).length} уроков всего приложения.
                </p>
              ) : found.length === 0 ? (
                <p className="px-4 py-6 text-sm text-center ms-rise" style={{ color: COLORS.inkSoft }}>Ничего не найдено</p>
              ) : found.map((f, i) => (
                <button key={f.key} onClick={() => { setQ(""); setOpen(false); onGo(f.key); }}
                  className="w-full text-left px-4 py-3 ms-rise" style={{ borderBottom: `1px solid ${COLORS.line}`, animationDelay: `${Math.min(i, 6) * 25}ms` }}>
                  <div className="flex items-center gap-2 mb-1">
                    <p className="text-sm font-medium truncate flex-1" style={{ color: COLORS.ink }}>{f.label}</p>
                    <span className="text-xs px-1.5 py-0.5 rounded flex-shrink-0" style={{ background: COLORS.paperDeep, color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{f.where}</span>
                  </div>
                  {f.snippet && <p className="text-xs leading-relaxed" style={{ color: COLORS.inkSoft }}>{f.snippet}</p>}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

function GlobalSearch({ onGo }) {
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(false);
  const inputRef = React.useRef(null);

  /* Ставим фокус после открытия окна — безопаснее, чем autoFocus. */
  useEffect(() => {
    if (open && inputRef.current) {
      const id = setTimeout(() => { try { inputRef.current.focus(); } catch (e) { /* не критично */ } }, 30);
      return () => clearTimeout(id);
    }
  }, [open]);

  const index = useMemo(() => {
    const out = [];
    MASTER_MAP.forEach((sec) => sec.topics.forEach((t) =>
      out.push({ key: t.key, label: t.label, sec: sec.title, screen: "economics-picker", tag: "Экономика", color: COLORS.sage })));
    FINLIT_MAP.forEach((sec) => sec.topics.forEach((t) =>
      out.push({ key: t.key, label: t.label, sec: sec.title, screen: "finlit", tag: "Фин. грамотность", color: COLORS.amber })));
    BIZ_MAP.forEach((sec) => sec.topics.forEach((t) =>
      out.push({ key: t.key, label: t.label, sec: sec.title, screen: "biz", tag: "Основы бизнеса", color: COLORS.rust })));
    SOCIAL_CURRICULUM.forEach((b) => b.subtopics.forEach((t) =>
      out.push({ key: t.key, label: t.label, sec: b.title, screen: "social", tag: "Обществознание", color: COLORS.teal })));
    return out;
  }, []);

  const found = useMemo(() => {
    const needle = q.trim().toLowerCase();
    if (needle.length < 2) return [];
    return index.filter((x) => x.label.toLowerCase().includes(needle) || x.sec.toLowerCase().includes(needle)).slice(0, 12);
  }, [q, index]);

  /* Ctrl+K или / открывают поиск, Escape закрывает. */
  useEffect(() => {
    const onKey = (e) => {
      const inField = e.target && ["INPUT", "TEXTAREA"].includes(e.target.tagName);
      if ((e.key === "k" && (e.metaKey || e.ctrlKey)) || (e.key === "/" && !inField)) {
        e.preventDefault(); setOpen(true);
      } else if (e.key === "Escape") { setOpen(false); setQ(""); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <>
      <button onClick={() => setOpen(true)}
        className="flex items-center gap-2 px-4 py-2.5 rounded-full text-sm"
        style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, color: COLORS.inkSoft }}>
        <Search size={15} />
        <span className="hidden sm:inline">Поиск по темам</span>
        <span className="hidden sm:inline text-xs px-1.5 py-0.5 rounded"
          style={{ background: COLORS.paperDeep, fontFamily: "'IBM Plex Mono', monospace" }}>/</span>
      </button>

      {open && (
        <div className="fixed inset-0 z-50 flex items-start justify-center pt-24 px-4"
          style={{ background: "rgba(0,0,0,0.35)" }}
          onClick={() => { setOpen(false); setQ(""); }}>
          <div className="w-full max-w-xl overflow-hidden"
            style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, borderRadius: 24, boxShadow: "0 16px 48px rgba(0,0,0,0.25)" }}
            onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-2 px-4 py-3" style={{ borderBottom: `1px solid ${COLORS.line}` }}>
              <Search size={16} color={COLORS.inkSoft} />
              <input ref={inputRef} value={q} onChange={(e) => setQ(e.target.value)}
                placeholder="Название темы или раздела…"
                className="flex-1 bg-transparent text-sm outline-none" style={{ color: COLORS.ink }} />
              <button onClick={() => { setOpen(false); setQ(""); }} style={{ color: COLORS.inkSoft }}>
                <X size={16} />
              </button>
            </div>
            <div style={{ maxHeight: 380, overflowY: "auto" }}>
              {q.trim().length < 2 ? (
                <p className="px-4 py-6 text-sm text-center" style={{ color: COLORS.inkSoft }}>
                  Введите минимум два символа. Поиск идёт по {index.length} темам всех разделов.
                </p>
              ) : found.length === 0 ? (
                <p className="px-4 py-6 text-sm text-center ms-rise" style={{ color: COLORS.inkSoft }}>Ничего не найдено</p>
              ) : (
                found.map((f, i) => (
                  <button key={f.screen + f.key}
                    onClick={() => { setQ(""); setOpen(false); onGo(f.screen, f.key); }}
                    className="w-full text-left px-4 py-2.5 flex items-center gap-3 ms-rise"
                    style={{ borderBottom: `1px solid ${COLORS.line}`, animationDelay: `${Math.min(i, 6) * 25}ms` }}>
                    <span style={{ width: 3, height: 30, background: f.color, borderRadius: 2, flexShrink: 0 }} />
                    <div className="min-w-0 flex-1">
                      <p className="text-sm truncate" style={{ color: COLORS.ink }}>{f.label}</p>
                      <p className="text-xs truncate" style={{ color: COLORS.inkSoft }}>{f.sec}</p>
                    </div>
                    <span className="text-xs px-2 py-0.5 rounded flex-shrink-0"
                      style={{ background: COLORS.paperDeep, color: f.color, fontFamily: "'IBM Plex Mono', monospace" }}>{f.tag}</span>
                  </button>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
}


/* ============================================================================
   МОДУЛЬ «ТЕСТОВАЯ ЧАСТЬ» — отдельный трек, банк реальных вариантов по номерам
   заданий ЕГЭ. Пока наполнено задание №1 (159 вариантов), структура рассчитана
   на добавление остальных номеров.
============================================================================ */

function TestBankApp({ onBack, theme, onToggleTheme }) {
  const [taskNum, setTaskNum] = useState(1);
  const [idx, setIdx] = useState(0);
  const [result, setResult] = useState(null);
  const [stats, setStats] = useState({ right: 0, total: 0 });
  const [wordTypeFilter, setWordTypeFilter] = useState(null);
  const inputRef = React.useRef(null);
  const storeKey = "testbank";

  useEffect(() => {
    (async () => {
      try {
        const r = await window.storage.get(storeKey + "-stats");
        if (r) setStats(JSON.parse(r.value));
      } catch (e) { /* первый запуск */ }
    })();
  }, []);

  const persist = useCallback(async (k, v) => {
    try { await window.storage.set(storeKey + "-" + k, JSON.stringify(v), false); } catch (e) { /* не критично */ }
  }, []);

  const BANKS = { 1: TASK1_BANK };
  const bank = BANKS[taskNum] || [];
  const wordTypes = useMemo(() => [...new Set(bank.map((t) => t.wordType))].sort(), [bank]);
  const pool = wordTypeFilter ? bank.filter((t) => t.wordType === wordTypeFilter) : bank;
  const cur = pool.length ? pool[idx % pool.length] : null;

  function checkAnswer() {
    if (!cur) return;
    const raw = inputRef.current ? inputRef.current.value : "";
    const norm = raw.trim().toLowerCase().replace(/ё/g, "е").replace(/[.,!?;]/g, "");
    const variants = (cur.altAnswers || [cur.a]).map((a) => a.toLowerCase().replace(/ё/g, "е"));
    const ok = variants.includes(norm) && norm.length > 0;
    setResult({ ok, given: raw.trim() });
    setStats((p) => { const n = { right: p.right + (ok ? 1 : 0), total: p.total + 1 }; persist("stats", n); return n; });
  }

  return (
    <div className="min-h-screen w-full" style={{ background: pageBackground(COLORS.teal), backgroundSize: PAGE_BG_SIZE, color: COLORS.ink, fontFamily: "'Figtree', ui-sans-serif, sans-serif" }}>
      <header className="max-w-3xl mx-auto px-6 pt-10 pb-6">
        <div className="flex items-start justify-between gap-4 flex-wrap">
          <div>
            <button onClick={onBack} className="text-xs mb-2 flex items-center gap-1" style={{ color: COLORS.inkSoft }}>
              <ArrowLeft size={13} /> На главный экран
            </button>
            <p className="text-xs tracking-widest uppercase" style={{ color: COLORS.teal, fontFamily: "'IBM Plex Mono', monospace" }}>ЕГЭ · банк по номерам заданий</p>
            <h1 className="text-3xl sm:text-4xl mt-1" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700 }}>Тестовая часть</h1>
          </div>
          <div className="flex items-center gap-2">
            <SessionTimer />
            <button onClick={onToggleTheme} className="flex items-center gap-2 px-4 py-2.5 rounded-full" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>
              {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-3xl mx-auto px-6 pb-20">
        <div className="rounded-xl p-4 mb-4" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
          <p className="text-xs mb-3" style={{ color: COLORS.inkSoft }}>
            Реальные тексты из открытого банка заданий ФИПИ (задание №1 — логико-смысловая связь).
            Каждый фрагмент показывает минимальный контекст вокруг пропуска. Впишите слово, которое туда подходит.
          </p>
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div className="flex gap-1.5 flex-wrap">
              <button onClick={() => setTaskNum(1)} className="text-xs font-medium px-3 py-1.5 rounded-2xl"
                style={{ background: taskNum === 1 ? COLORS.onyx : COLORS.paperDeep, color: taskNum === 1 ? COLORS.onyxText : COLORS.inkSoft }}>
                Задание №1 ({TASK1_BANK.length})
              </button>
            </div>
            {stats.total > 0 && (
              <span className="text-xs" style={{ color: toneForValue(Math.round(stats.right / stats.total * 100)), fontFamily: "'IBM Plex Mono', monospace" }}>
                точность {Math.round(stats.right / stats.total * 100)}% ({stats.right}/{stats.total})
              </span>
            )}
          </div>
        </div>

        <div className="flex gap-1.5 flex-wrap mb-4">
          <button onClick={() => { setWordTypeFilter(null); setIdx(0); setResult(null); }}
            className="text-xs font-medium px-2.5 py-1.5 rounded-2xl"
            style={{ background: !wordTypeFilter ? COLORS.teal : COLORS.paperDeep, color: !wordTypeFilter ? "#FFF" : COLORS.inkSoft }}>
            Все ({bank.length})
          </button>
          {wordTypes.map((wt) => {
            const n = bank.filter((t) => t.wordType === wt).length;
            const on = wordTypeFilter === wt;
            return (
              <button key={wt} onClick={() => { setWordTypeFilter(on ? null : wt); setIdx(0); setResult(null); }}
                className="text-xs font-medium px-2.5 py-1.5 rounded-2xl"
                style={{ background: on ? COLORS.teal : COLORS.paperDeep, color: on ? "#FFF" : COLORS.inkSoft }}>
                {wt} · {n}
              </button>
            );
          })}
        </div>

        {!cur ? (
          <div className="rounded-2xl p-10 text-center" style={{ background: COLORS.surface, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
            <p style={{ color: COLORS.inkSoft }}>Заданий по этому фильтру нет.</p>
          </div>
        ) : (
          <div>
            <div className="text-xs mb-2" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{(idx % pool.length) + 1} / {pool.length}</div>
            <div className="rounded-2xl p-6" style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, boxShadow: COLORS.cardShadow }}>
              <Pill tone="teal">{cur.wordType}</Pill>
              <p className="text-sm leading-relaxed mt-3 mb-3" style={{ color: COLORS.ink }}>{cur.q}</p>
              <div className="rounded-lg p-4 mb-4" style={{ background: COLORS.paperDeep, fontFamily: "'Figtree', sans-serif", lineHeight: 1.7 }}>
                <p className="text-sm" style={{ color: COLORS.ink }}>{cur.frag}</p>
              </div>
              {!result ? (
                <div className="flex gap-2">
                  <input key={cur.id} ref={inputRef} defaultValue="" placeholder="впиши слово"
                    onKeyDown={(e) => { if (e.key === "Enter") checkAnswer(); }}
                    className="flex-1 px-3 py-2.5 rounded-2xl text-sm"
                    style={{ background: COLORS.paperDeep, border: `1px solid ${COLORS.line}`, color: COLORS.ink, fontFamily: "'IBM Plex Mono', monospace" }} />
                  <button onClick={checkAnswer} className="px-5 py-2.5 rounded-full text-sm font-semibold" style={{ background: COLORS.onyx, color: COLORS.onyxText }}>Проверить</button>
                </div>
              ) : (
                <div>
                  <div className="rounded-2xl p-4 mb-3" style={{ background: result.ok ? COLORS.sageSoft : COLORS.rustSoft }}>
                    <p className="text-sm font-semibold mb-1" style={{ color: result.ok ? COLORS.sage : COLORS.rust }}>
                      {result.ok ? "✓ Верно" : `✕ Неверно. Твой ответ: ${result.given || "—"} · Правильный: ${cur.a}`}
                    </p>
                    <p className="text-sm leading-relaxed mt-2" style={{ color: COLORS.ink }}>{cur.why}</p>
                  </div>
                  <button onClick={() => { setIdx((i) => i + 1); setResult(null); }}
                    className="w-full py-2.5 rounded-full text-sm font-semibold" style={{ background: COLORS.teal, color: "#FFF" }}>
                    Следующее задание →
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

function HomeScreen({ onSelect, theme, onToggleTheme }) {
  const [greeting] = useState(() => GREETINGS[Math.floor(Math.random() * GREETINGS.length)]);
  const [stats, setStats] = useState(null);

  /* Собираем сводку по всем разделам, чтобы показать прогресс прямо на плитках. */
  useEffect(() => {
    (async () => {
      const read = async (key) => {
        try { const r = await window.storage.get(key); return r ? JSON.parse(r.value) : null; }
        catch (e) { return null; }
      };
      const [econChecked, socChecked, fgChecked, bzChecked, streak, time] = await Promise.all([
        read("topic-checked"), read("social-checked"),
        read("fg-checked"), read("bz-checked"),
        read("streak"), read("time-v2"),
      ]);
      const pct = (obj, total) => {
        if (!obj || !total) return 0;
        return Math.round((Object.values(obj).filter(Boolean).length / total) * 100);
      };
      const econCore = MASTER_MAP.filter((x) => (x.tier || 9) <= 2).flatMap((x) => x.topics).length;
      const fgCore = FINLIT_MAP.filter((x) => (x.tier || 9) <= 2).flatMap((x) => x.topics).length;
      const bzCore = BIZ_MAP.filter((x) => (x.tier || 9) <= 2).flatMap((x) => x.topics).length;
      setStats({
        "economics-picker": pct(econChecked, econCore),
        social: pct(socChecked, SOCIAL_CURRICULUM.flatMap((b) => b.subtopics).length),
        finlit: pct(fgChecked, fgCore),
        biz: pct(bzChecked, bzCore),
        streak: streak?.count || 0,
        totalHours: time ? Math.round((time.total || 0) / 3600) : 0,
        todayMin: time ? Math.round((time.today || 0) / 60) : 0,
      });
    })();
  }, []);

  const olympTiles = [
    {
      id: "economics-picker", title: "Экономика", subtitle: "ВсОШ · Высшая проба",
      description: "«Высшая проба» разобрана полностью: 115 тем, 17 практикумов, эталонные решения задач.",
      icon: Brain, accent: COLORS.sage, accentSoft: COLORS.sageSoft, ready: true,
    },
    {
      id: "finlit", title: "Финансовая грамотность", subtitle: "Высшая проба",
      description: "ЦФА, ипотека, кэрри-трейд, налоги. Все задания 2025 и 2026 с критериями.",
      icon: Coins, accent: COLORS.amber, accentSoft: COLORS.amberSoft, ready: true,
    },
    {
      id: "biz", title: "Основы бизнеса", subtitle: "Высшая проба",
      description: "SWOT, критическое мышление, юнит-экономика, NPV, DMAIC и менеджмент.",
      icon: Briefcase, accent: COLORS.rust, accentSoft: COLORS.rustSoft, ready: true,
    },
    {
      id: "prepplan30", title: "План подготовки — 30 дней", subtitle: "Экономика · Бизнес · ФинГрам",
      description: "Сравнение отборочного этапа по годам, прогноз тем, понедельный график на все три профиля.",
      icon: CalendarDays, accent: COLORS.blue, accentSoft: COLORS.blueSoft, ready: true,
    },
  ];

  const egeTiles = [
    {
      id: "social", title: "Обществознание", subtitle: "ЕГЭ",
      description: "75 тем кодификатора, 145 карточек, 458 тестовых заданий, разбор части 2.",
      icon: GraduationCap, accent: COLORS.teal, accentSoft: COLORS.tealSoft, ready: true,
    },
    {
      id: "math", title: "Профильная математика", subtitle: "ЕГЭ",
      description: "Раздел подготовлен к наполнению — структура появится после разбора кодификатора.",
      icon: Sigma, accent: COLORS.blue, accentSoft: COLORS.blueSoft, ready: false,
    },
    {
      id: "russian", title: "Русский язык", subtitle: "ЕГЭ",
      description: "Стратегия «с нуля до 70 баллов». Ударение, паронимы, грамматика, сочинение по тексту.",
      icon: PenLine, accent: COLORS.rust, accentSoft: COLORS.rustSoft, ready: true,
    },
  ];


  return (
    <div
      className="min-h-screen w-full flex flex-col relative overflow-hidden"
      style={{
        background: pageBackground(),
        backgroundSize: PAGE_BG_SIZE,
        color: COLORS.ink,
        fontFamily: "'Figtree', ui-sans-serif, sans-serif",
      }}
    >
      {/* Подпись страницы: едва различимые оси и две кривые — пересечение спроса
          и предложения. Тематический знак, который не мешает читать содержимое. */}
      <svg aria-hidden="true" viewBox="0 0 400 260" preserveAspectRatio="none"
        style={{ position: "absolute", right: "-4%", bottom: "-2%", width: "min(52vw, 620px)",
                 height: "auto", opacity: 0.055, pointerEvents: "none", zIndex: 0 }}>
        <line x1="40" y1="20" x2="40" y2="220" stroke={COLORS.ink} strokeWidth="2" />
        <line x1="40" y1="220" x2="380" y2="220" stroke={COLORS.ink} strokeWidth="2" />
        <path d="M60 40 L360 200" stroke={COLORS.sage} strokeWidth="3" fill="none" strokeLinecap="round" />
        <path d="M60 200 L360 40" stroke={COLORS.rust} strokeWidth="3" fill="none" strokeLinecap="round" />
        <circle cx="210" cy="120" r="7" fill={COLORS.ink} />
      </svg>

      <div className="flex justify-end items-center gap-2 p-6 flex-wrap relative" style={{ zIndex: 20 }}>
        <button onClick={() => onSelect("plan")}
          className="flex items-center gap-2 px-4 py-2.5 rounded-full text-sm"
          style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.blue}`, color: COLORS.blue }}>
          <CalendarDays size={15} /> <span className="hidden sm:inline">План подготовки</span>
        </button>
        <GlobalSearch onGo={(screen) => onSelect(screen)} />
        <div className="flex items-center gap-2">
        <SessionTimer />
        <button
          onClick={onToggleTheme}
          aria-label={theme === "light" ? "Включить тёмную тему" : "Включить светлую тему"}
          className="flex items-center gap-2 px-4 py-2.5 rounded-full"
          style={{ background: COLORS.onyx, color: COLORS.onyxText }}
        >
          {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
        </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-6 pb-10 pt-2 relative" style={{ minHeight: 0, zIndex: 1 }}>
        <p className="text-xs tracking-widest uppercase mb-4 flex items-center gap-2" style={{ color: COLORS.teal, fontFamily: "'IBM Plex Mono', monospace" }}>
          <span style={{ fontWeight: 700, letterSpacing: "0.08em" }}>MIRSTUDY</span>
          <span style={{ opacity: 0.5 }}>·</span>
          <span style={{ opacity: 0.75 }}>Личный учебный тренажёр</span>
        </p>
        <h1
          className="text-center max-w-2xl text-3xl sm:text-4xl leading-snug mb-14"
          style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700, color: COLORS.ink }}
        >
          {greeting}
        </h1>

        <div className="grid md:grid-cols-2 gap-7 w-full max-w-4xl">
          {[["Олимпиады", olympTiles, COLORS.sage], ["ЕГЭ", egeTiles, COLORS.teal]].map(([groupName, list, groupColor]) => (
            <div key={groupName}>
              <div className="flex items-center gap-2 mb-3.5">
                <span style={{ width: 6, height: 6, borderRadius: 3, background: groupColor }} />
                <p className="text-xs uppercase tracking-widest"
                  style={{ color: groupColor, fontFamily: "'IBM Plex Mono', monospace" }}>{groupName}</p>
                <span className="flex-1" style={{ height: 1, background: COLORS.line }} />
              </div>
              <div className="space-y-3">
                {list.map((tile, ti) => (
                  <button
                    key={tile.id}
                    onClick={() => tile.ready && onSelect(tile.id)}
                    disabled={!tile.ready}
                    className="w-full text-left p-5 transition ms-rise"
                    style={{
                      background: COLORS.surfaceSolid,
                      border: `1px solid ${COLORS.line}`,
                      borderRadius: 22,
                      opacity: tile.ready ? 1 : 0.5,
                      cursor: tile.ready ? "pointer" : "default",
                      animationDelay: `${ti * 40}ms`,
                    }}
                  >
                    <div className="flex items-start gap-3">
                      <div className="w-10 h-10 flex items-center justify-center flex-shrink-0" style={{ background: tile.accentSoft, borderRadius: 999 }}>
                        <tile.icon size={18} color={tile.accent} />
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="text-xs uppercase tracking-wide" style={{ color: tile.accent, fontFamily: "'IBM Plex Mono', monospace" }}>{tile.subtitle}</p>
                        <p className="text-base mt-0.5" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700 }}>{tile.title}</p>
                      </div>
                    </div>
                    <p className="text-xs mt-2.5 leading-relaxed" style={{ color: COLORS.inkSoft }}>{tile.description}</p>
                    {stats && tile.ready && (
                      <div className="mt-3">
                        <div className="w-full h-1.5 rounded-full" style={{ background: COLORS.paperDeep }}>
                          <div className="h-1.5 rounded-full transition-all"
                            style={{ width: `${Math.min(stats[tile.id] || 0, 100)}%`, background: tile.accent }} />
                        </div>
                        <p className="text-xs mt-1.5" style={{ color: COLORS.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                          {stats[tile.id] > 0 ? `пройдено ${stats[tile.id]}%` : "ещё не начато"}
                        </p>
                      </div>
                    )}
                    {!tile.ready && (
                      <p className="text-xs mt-3 font-medium" style={{ color: COLORS.inkSoft }}>Скоро →</p>
                    )}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Перерыв: игры для отдыха, отдельно от учебных разделов. */}
        <div className="w-full max-w-4xl mt-7">
          <div className="flex items-center gap-2 mb-3.5">
            <span style={{ width: 6, height: 6, borderRadius: 3, background: COLORS.amber }} />
            <p className="text-xs uppercase tracking-widest" style={{ color: COLORS.amber, fontFamily: "'IBM Plex Mono', monospace" }}>Перерыв</p>
            <span className="flex-1" style={{ height: 1, background: COLORS.line }} />
          </div>
          <button onClick={() => onSelect("lavka")} className="w-full text-left p-5 transition ms-rise flex items-center gap-4"
            style={{ background: COLORS.surfaceSolid, border: `1px solid ${COLORS.line}`, borderRadius: 22 }}>
            <span className="text-3xl" aria-hidden="true">🍋</span>
            <div className="min-w-0 flex-1">
              <p className="text-base" style={{ fontFamily: "'Figtree', sans-serif", fontWeight: 700 }}>Лавка</p>
              <p className="text-xs mt-1 leading-relaxed" style={{ color: COLORS.inkSoft }}>
                Уютный тайкун: ставишь цену, закупаешь товар, смотришь, как идёт день. Жара, налоги, потолок цен и конкурент по соседству — нащупай MR = MC руками.
              </p>
            </div>
            <ChevronRight size={18} color={COLORS.inkSoft} />
          </button>
        </div>

        {stats && (stats.streak > 0 || stats.totalHours > 0) && (
          <div className="flex gap-6 mt-10 flex-wrap justify-center">
            {[
              [stats.streak, stats.streak === 1 ? "день подряд" : "дней подряд", COLORS.amber],
              [stats.todayMin, "минут сегодня", COLORS.blue],
              [stats.totalHours, "часов всего", COLORS.teal],
            ].map(([v, label, c]) => (
              <div key={label} className="text-center">
                <div className="text-2xl font-bold" style={{ color: c, fontFamily: "'IBM Plex Mono', monospace" }}>{v}</div>
                <div className="text-xs mt-0.5" style={{ color: COLORS.inkSoft }}>{label}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/* ============================= ПЕРЕРЫВ · ЛАВКА =============================
   Игра вынесена в модуль: логика — src/games/lavka/model.js, экраны — src/games/lavka/ui.jsx.
   Сохранение — ключ "lavka-save": правило newer в ProgressMerge и запись в BACKUP_KEYS остались здесь, в App.jsx. */

/* ============================= КОРНЕВОЙ КОМПОНЕНТ ============================= */

export default function AppRoot() {
  const [screen, setScreen] = useState("home");
  const [rootTheme, setRootTheme] = useState("light");

  useEffect(() => {
    window.storage
      .get("ui-theme")
      .then((r) => {
        if (r) setRootTheme(JSON.parse(r.value));
      })
      .catch(() => {});
  }, []);

  function toggleRootTheme() {
    const next = rootTheme === "light" ? "dark" : "light";
    setRootTheme(next);
    window.storage.set("ui-theme", JSON.stringify(next), false).catch(() => {});
  }

  Object.assign(COLORS, rootTheme === "dark" ? DARK_COLORS : LIGHT_COLORS);

  if (screen === "economics-picker") return <OlympiadPickerScreen onSelect={setScreen} onBack={() => setScreen("home")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "vysshaya-proba") return <EconomicsApp onBack={() => setScreen("economics-picker")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "vsosh") return <VsoshApp onBack={() => setScreen("economics-picker")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "plan") return <StudyPlanScreen onBack={() => setScreen("home")} onGo={setScreen} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "finlit") return <TrackApp track="finlit" onBack={() => setScreen("home")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "biz") return <TrackApp track="biz" onBack={() => setScreen("home")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "prepplan30") return <PrepPlan30Screen onBack={() => setScreen("home")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "russian") return <TrackApp track="russian" onBack={() => setScreen("home")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "social") return <SocialApp onBack={() => setScreen("home")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  if (screen === "lavka") return <LavkaScreen onBack={() => setScreen("home")} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
  return <HomeScreen onSelect={setScreen} theme={rootTheme} onToggleTheme={toggleRootTheme} />;
}
